MultiLanguageSpellData['de'][466011] = {name = "Leuchtendo der Lodernde", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Der VIP unter den VIPs des Garbagio zu sein, hat seine Vorteile, darunter die Schlüssel zum ehemaligen Metzelmeister. Durch hochmoderne Goblintechnologie schafft er ganze 30 Meter auf den Liter!\"\nVerkäufer:\nAndo die Knarre\nZone:\nBefreiung von Lorenhall\nKosten:\n777"}
MultiLanguageSpellData['de'][466012] = {name = "Donnertrommelfehlzündung", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Wurde nach einem besonders grausigen Aufeinandertreffen von der Tribüne des Kessels geborgen. Auf die Frage, ob es sich um einen Blindgänger handelt, antwortete Torqs Management mit: \"Vermutlich?\"\"\nHändler:\nAndo die Knarre\nZone:\nBefreiung von Lorenhall\nKosten:\n500"}
MultiLanguageSpellData['de'][466013] = {name = "Ockerfarbene Zustellungsrakete", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Bringt Pakete und Passagiere von A nach B. Und zwar mir Stil!\"\nVerkäufer:\nSchredd der Verschrotter\nZone:\nLorenhall\nKosten:\n11.375"}
MultiLanguageSpellData['de'][466014] = {name = "Liefermodul des Dampfdruckkartells", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Liefert Euch einen kurzen Trip oder Euren Gegnern eine gewaltige Explosion!\"\nBeute von:\nSchatz des Dampfdruckkartells\nZone:\nLorenhall"}
MultiLanguageSpellData['de'][466016] = {name = "Oberskimmer Spezial", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Smaks ist sich sicher, dass die Rakete mitten im Flug nicht explodieren wird. Absolut. Total. Zu 100% sicher.\"\nVerkäufer:\nSmaks Oberskimmer\nZone:\nLorenhall\nKosten:\n11.375"}
MultiLanguageSpellData['de'][466017] = {name = "Innovationsermittler", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Wenn der beste Weg zu einer guten Idee wirklich schnell ist.\"\nVerkäufer:\nSkedgit Glutfransen\nZone:\nLorenhall\nKosten:\n25"}
MultiLanguageSpellData['de'][466018] = {name = "Verwüster der Düsternisverschmolzenen", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Exzellent, wenn es darum geht, eine Riesensauerei zu hinterlassen. Weniger gut darin, sie wieder zu beseitigen.\"\nVerkäufer:\nLage Fiesmöpp\nZone:\nLorenhall\nKosten:\n11.375"}
MultiLanguageSpellData['de'][466019] = {name = "Schwarzmeerschredder Deluxe Mk. 2", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Man sollte lieber nicht hinterfragen, was mit Mk. 1 passiert ist.\"\nVerkäuferin:\nBootsmann HartiZone:\nLorenhallKosten:\n8.125"}
MultiLanguageSpellData['de'][466020] = {name = "Personalisierter Goblinverschrotter", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Goblinschredder haben immer wieder bewiesen, in vielen verschiedenen Anwendungen nützlich zu sein, wie beim Holzfällen und Transport. Dieses Modell wurde für den Einsatz mit S.C.H.R.O.T.T. umfunktioniert.\"\nBeute:\nDurchwühlter Schrotthaufen\nZone:\nLorenhall"}
MultiLanguageSpellData['de'][466021] = {name = "Violetter Goblinschredder", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Dieser Schredder wurde liebevoll mit einer rostabweisenden Farbe lackiert, um bleibenden Glanz zu gewährleisten.\"\nBeute von:\nVersand & Logistik\nZone:\nLorenhall"}
MultiLanguageSpellData['de'][466022] = {name = "Ko-ordinator der Venture Company", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Gebaut, um jegliche Unterfangen der Venture Company an vorderster Front zu unterstützen.\"\nBeute von:\nSchatz der Venture Co.\nZone:\nLorenhall"}
MultiLanguageSpellData['de'][466023] = {name = "Anlagenbefürworter", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Versichert anderen, dass Eure Anlagen genau da sind, wo sie sein sollten.\"\nVerkäufer:\nSkedgit GlutfransenZone:\nLorenhallKosten:\n25"}
