MultiLanguageSpellData['de'][466025] = {name = "Margenmanipulator", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Stellt sicher, dass es immer einen marginalen Abstand zwischen Euch und dem absoluten Tiefpunkt gibt.\"\nVerkäufer:\nSkedgit Glutfransen\nZone:\nLorenhall\nKosten:\n25"}
MultiLanguageSpellData['de'][466026] = {name = "Geborgene Flugmaschine des Goblingeldsacks", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Diese Flugmaschine, einst geschätzter Besitz der Goblineliten, wurde leider dem Schrotthaufen überlassen, nachdem etwas auf dem Markt erschien, das größer, auffälliger und explosiver war.\"\nBeute:\nMüll des Garbagio\nZone:\nLorenhall"}
MultiLanguageSpellData['de'][466027] = {name = "Spionagedrohne der Düsternisverschmolzenen", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Perfekt für alle, die die Karriereleiter erklimmen wollen, indem sie alles zu IHRER Angelegenheit machen.\"\nWeltquest:\nFällmittel der Düsternisverschmolzenen\nZone:\nLorenhall"}
