MultiLanguageSpellData['de'][467024] = {name = "Kaja'Cola-Träger", additional_info = "[q]Verlegte Kuriositäten haben jetzt einmal pro Tiefe eine Chance von 35%, 1 Kaja'Colas zu enthalten, und Brann beschwört jetzt ein Sechserpack Kaja'Cola, wenn er ein Lagerfeuer macht.\n\n Es gibt verschiedene Kaja'Cola-Geschmacksrichtungen und jede hat einen eigenen Effekt, der beim Einsammeln wirkt."}
MultiLanguageSpellData['de'][467026] = {name = "Goblomagnetische Hüpfgranate", additional_info = "[q]Brann hat eine Chance, im Kampf eine goblomagnetische Hüpfgranate auf ein Ziel zu werfen, die mäßigen Naturschaden verursacht und eine Chance von 20% hat, das Ziel für 1.5 Sek. zu betäuben. Anschließend besteht eine Chance von 25%, dass die Granate zu einem neuen Ziel hüpft.\n\n Die Granate kann bedenkenlos zu Gruppenmitgliedern springen."}
MultiLanguageSpellData['de'][467029] = {name = "Einschlagsumwandlungsmatrix", additional_info = "[q]Zu Kampfbeginn aktiviert Brann für 10 Sek. die Umwandlungsmatrix. Ein kleiner Anteil von sämtlichem Schaden, den die Gruppe währenddessen verursacht, erhöht den Primärwert. Die Erhöhung wird unter den Gruppenmitgliedern aufgeteilt.\n\n Wenn sich die Umwandlungsmatrix deaktiviert, bleibt die Erhöhung des Primärwerts noch 10 Sek. lang bestehen. Dieser Effekt kann nur einmal alle 2 Min. auftreten."}
MultiLanguageSpellData['de'][467031] = {name = "Schwarzblutstrom", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Schwarzblut rinnt vom Fabrikdach und verursacht alle 0.5 Sek. 14 Schattenschaden."}
