MultiLanguageSpellData['de'][467033] = {name = "B3U13RÄUB-R", additional_info = "[q]Tastet die Umgebung alle 60 Sek. oder 5 Sek. nach Kampfbeginn ab, hebt verlegte Kuriositäten hervor und lässt Gegner mit weniger als 95% Gesundheit 10 Sek. lang 4% mehr Schaden erleiden."}
MultiLanguageSpellData['de'][467034] = {name = "Rückentwickelte Goblintodesbombe", additional_info = "[q]Wenn die Gesundheit eines Spielcharakters während eines Kampfes unter 50% fällt, wirft Brann eine riesige Bombe, die beim Einschlag explodiert.\n\n Die Explosion stößt umstehende Gegner zurück, verlangsamt sie 5 Sek. lang um 45% und heilt Gruppenmitglieder in der Nähe um 35% ihrer maximalen Gesundheit. Kann nur einmal alle 1.5 Min. auftreten."}
MultiLanguageSpellData['de'][467035] = {name = "Absurd großer Magnet", additional_info = "[q]Wenn Brann ' Sammelwerkzeuge ' einsetzt, besteht eine Chance von 100%, weggeworfene Panzerung zu magnetisieren. Diese Panzerung haftet an Gruppenmitgliedern und gewährt ihnen 5% ihrer maximalen Gesundheit als Schild, der sich außerhalb des Kampfes regeneriert.\n\n Sammelwerkzeuge\nBrann setzt seine Sammelwerkzeuge ein, um Spielercharakteren zu helfen, zusätzliches Gold, Erz, Leder, zusätzliche Kräuter, Fische und Schätze zu finden."}
MultiLanguageSpellData['de'][467036] = {name = "Raketenausrüstung mit Biotreibstoff", additional_info = "[q]Gruppenmitglieder werden mit Raketenausrüstung mit Biotreibstoff ausgerüstet.\n\n Biotreibstoff\n Jeder getötete Gegner füllt die Raketenausrüstung mit Biotreibstoff auf und erhöht damit 10 Sek. lang die Bewegungsgeschwindigkeit um 2% und das Tempo um 2%. Bis zu 10-mal stapelbar."}
MultiLanguageSpellData['de'][467037] = {name = "Angeklopfter Erweiterungschip", additional_info = "[q]Branns maximale Gesundheit ist um 4% erhöht und er verursacht 20% mehr Schaden und Heilung.\n\n Im Kampf kann Brann von mechanischen Robotern anvisiert werden, die sich zerstören oder vertreiben lassen. Wenn sie Brann erreichen, erleidet er 30% seiner maximalen Gesundheit als Schaden und wird für 5 Sek. betäubt."}
