MultiLanguageSpellData['de'][470168] = {name = "Cyrces Zephir", additional_info = "Sofort\n[q]Während Ihr Cyrces Reif angelegt habt und Euch auf der Sireneninsel befindet, haben Eure Zauber und Fähigkeiten eine Chance, Cyrces Zephir zu beschwören, der im Verlauf von 3 Sek. alle vorhandenen Fähigkeiten des singenden Citrins einsetzt."}
MultiLanguageSpellData['de'][470169] = {name = "Diebe der Sirene", additional_info = "Sofort\n[q]Cyrces Reif markiert jetzt passiv unsichtbare Gegner, die versuchen, die Reichtümer der Sireneninsel zu stehlen. Sie lassen sich oft dabei überraschen, wie sie versuchen, flammengesegnetes Eisen von den stärksten Kreaturen der Insel zu stehlen."}
