MultiLanguageSpellData['de'][470194] = {name = "Eisstoß", additional_info = "{0.66% von Grundmana} {Nahkampfreichweite}\n{Sofort} {15 sek. Abklingzeit}\n[q]Trifft Euer Ziel mit einer eisigen Klinge, fügt ihm (285.66% der Angriffskraft) Frostschaden zu und verringert seine Bewegungsgeschwindigkeit 6 Sek. lang um 50%.\n\n 'Eisstoß' erhöht den Schaden Eures nächsten Einsatzes von 'Frostschock' um 100% und erzeugt 1 Stapel von 'Waffe des Mahlstroms'."}
MultiLanguageSpellData['de'][470197] = {name = "Segen des Meeresbewohners", additional_info = "Sofort\n[q]Erlangt in den Gewässern um die Sireneninsel die passive Fähigkeit, auf dem Meeresboden zu wandeln, Schätze unter Wasser zu finden und unter Wasser zu atmen sowie deutlich schneller zu schwimmen.\n\n Ihr müsst Cyrces Reif angelegt haben."}
MultiLanguageSpellData['de'][470200] = {name = "Feuerflöhe", additional_info = "Nahkampfreichweite\nSofort 2 min Abklingzeit\n[q]Tempo um 25% verringert.\n Chance von 10%, bei erlittenem Treffer Flöhe auf Verbündete überspringen zu lassen.\n(Procchance: 10%)"}
