MultiLanguageSpellData['de'][470669] = {name = "Widerhallender Tadel", additional_info = "[q]Gesetzlosigkeit\n Nach dem Verbrauch eines supergeladenen Combopunkts setzt Euer nächster Einsatz von 'Finsterer Stoß' außerdem 'Widerhallender Tadel' gegen das Ziel ein und verursacht (118% der Angriffskraft) körperlichen Schaden.\n\nMeucheln\n Nach dem Verbrauch eines supergeladenen Combopunkts setzt Euer nächster Einsatz von 'Verstümmeln' außerdem 'Widerhallender Tadel' gegen das Ziel ein und verursacht (118% der Angriffskraft) körperlichen Schaden.\n\nTäuschung\n Nach dem Verbrauch eines supergeladenen Combopunkts setzt Euer nächster Einsatz von 'Meucheln' außerdem 'Widerhallender Tadel' gegen das Ziel ein und verursacht (118% der Angriffskraft) körperlichen Schaden."}
MultiLanguageSpellData['de'][470670] = {name = "Prügelhagel", additional_info = "Sofort\n[q]Pro [(Angriffskraft * 6.25 * (1 + Vielseitigkeit))] Schaden, die Ihr verursacht, wird eine Aufladung von 'Prügelladung' erzeugt. Pro 240 Energie, die Ihr verbraucht, werden alle Aufladungen von 'Prügelladung' entfesselt und verursachen pro Aufladung (60% der Angriffskraft) körperlichen Schaden."}
MultiLanguageSpellData['de'][470671] = {name = "Widerhallender Tadel", additional_info = "Sofort\n[q]Nach dem Verbrauch eines supergeladenen Combopunkts setzt Euer nächster Einsatz von [ Düstere Klinge : 'Düstere Klinge' ] [ Täuschung : 'Meucheln' / Gesetzlosigkeit : 'Finsterer Stoß' /\n\nMeucheln\n'Verstümmeln' ] außerdem 'Widerhallender Tadel' gegen das Ziel ein und verursacht (118% der Angriffskraft) körperlichen Schaden."}
MultiLanguageSpellData['de'][470672] = {name = "Widerhallender Tadel", additional_info = "40 Meter Reichweite\nSofort\nBenötigt Einhändige Nahkampfwaffe\n[q]Nach dem Verbrauch eines supergeladenen Combopunkts setzt Euer nächster Einsatz von [ Düstere Klinge : 'Düstere Klinge' ] [ Täuschung : 'Meucheln' / Gesetzlosigkeit : 'Finsterer Stoß' /\n\nMeucheln\n'Verstümmeln' ] außerdem 'Widerhallender Tadel' gegen das Ziel ein und verursacht (118% der Angriffskraft) körperlichen Schaden."}
MultiLanguageSpellData['de'][470673] = {name = "Goblingetriebe", additional_info = "15 Meter Reichweite\nSofort 1.5 min Abklingzeit\n[q]Setzt ein 'Goblingetriebe' ein, das 30 Sek. lang bestehen bleibt und die Kampffähigkeiten von Euch und Euren Verbündeten in der Nähe verbessert. Innerhalb von 10 Metern um das Getriebe ist das Tempo um 15% erhöht."}
MultiLanguageSpellData['de'][470674] = {name = "Goblinischer Mechanokern", additional_info = "10 Meter Reichweite\nSofort\n[q]Eure Zauber und Fähigkeiten haben eine Chance, jene um Euch zu ermutigen und 107 Vielseitigkeit zu gewähren, die zwischen Euch und Verbündeten in der Nähe aufgeteilt wird.\n\n Die Vielseitigkeit wird für jeden betroffenen Verbündeten erhöht. Bis zu 5 Verbündete."}
MultiLanguageSpellData['de'][470675] = {name = "Ultimativer Noggenfogger Deluxe", additional_info = "13 Meter Reichweite\nSofort 2 min Abklingzeit\n[q]Beschwört einen Piraten der Schwarzmeer AG, der Euch 20 Sek. lang im Kampf beisteht."}
