MultiLanguageSpellData['de'][473677] = {name = "Bärenansturm", additional_info = "40 Meter Reichweite\nSofort\n[q]Brann beschwört den Bären der Familie, der sich in den Kampf stürzt und Gegner in die Luft schleudert.\n\n Der Bär setzt dann dazu an, mehrfach heftig aufzustampfen, was Schaden verursacht und einen Bereich entstehen lässt, der die Ausweichchance und maximale Gesundheit erhöht."}
MultiLanguageSpellData['de'][473678] = {name = "Bärenansturm", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Springt durch die Luft zu einem Zielort und schmettert mit zerstörerischer Gewalt auf den Boden, sodass alle Gegner innerhalb von 8 Metern (23.5% der Angriffskraft) körperlichen Schaden erleiden. [ Schutz : Schließt die Abklingzeit von 'Spott' ab ]"}
MultiLanguageSpellData['de'][473679] = {name = "B3U13RÄUB-R", additional_info = "100 Meter Reichweite\nSofort\n[q]Tastet die Umgebung alle 60 Sek. oder 5 Sek. nach Kampfbeginn ab, hebt verlegte Kuriositäten hervor und lässt Gegner mit weniger als 95% Gesundheit 10 Sek. lang 4% mehr Schaden erleiden."}
