MultiLanguageSpellData['de'][474067] = {name = "Zauberwarteschlange: Bronzebarts Braunbär", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Brann beschwört den Bären der Familie, der sich in den Kampf stürzt und Gegner in die Luft schleudert.\n\n Der Bär setzt dann dazu an, mehrfach heftig aufzustampfen, was Schaden verursacht und einen Bereich entstehen lässt, der die Ausweichchance und maximale Gesundheit erhöht."}
