MultiLanguageSpellData['de'][1215044] = {name = "Pazifistenausrüstung", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Während des Kampfes wird für 8 Sek. ein Pilot bestimmt. Daraufhin wird die Pazifistenausrüstung MK 1 an dessen Standort abgeworfen, wodurch dieser Immunität erhält, ihm 10 Sek. lang Kontrolle über die Ausrüstung gewährt wird und Gegner in der Nähe zurückgestoßen werden."}
