MultiLanguageSpellData['de'][1215611] = {name = "Schamanenklassenset, Wiederherstellung, 11.1, 4 Teile", additional_info = "[q]Wenn Ihr ' [ Wogendes Totem / Heilender Regen]' einsetzt, wird [ Wogendes Totem : 2 / 1] Verbündeten im Umkreis Versicherung! gewährt. Wenn Versicherung! verbraucht wird, heilt Euer nächster Einsatz von 'Kettenheilung', 'Heilende Woge' oder 'Welle der Heilung' [ Wogendes Totem : 10 / 10]% mehr Gesundheit."}
MultiLanguageSpellData['de'][1215613] = {name = "Paladinklassenset, Heilig, 11.1, 4 Teile", additional_info = "[q]Wenn 'Göttlicher Glockenschlag' Verbündete 8 Sek. lang heilt, werden diese mit Versicherung! belegt. Die Abklingzeit von 'Göttlicher Glockenschlag' wird jedes Mal, wenn Ihr Heilige Kraft verbraucht, um 1.0 Sek. verringert.\n(500ms Abklingzeit)"}
MultiLanguageSpellData['de'][1215616] = {name = "Unkontrollierter Ansturm", additional_info = "Sofort\n[q]Bront rast auf sein Ziel zu, fügt allen Spielercharakteren auf seinem Weg 7273348 körperlichen Schaden zu und betäubt sie für 2 Sek.\n\n Bronts Angriff ist so stark, dass er alle tickenden Zeitbomben auf seinem Weg wegschleudert."}
