MultiLanguageSpellData['de'][1215619] = {name = "Druidenklassenset, Wiederherstellung, 11.1, 4 Teile", additional_info = "[q]Euer 'Blühendes Leben' hat eine Chance von 30%, das Ziel für 10 Sek. mit Versicherung! zu belegen. Wenn Versicherung! verbraucht oder entfernt wird, hinterlässt sie auf ihrem Ziel für 15 Sek. einen regelmäßigen Heilungseffekt von 'Verjüngung', 'Nachwachsen' oder 'Wildwuchs', der aktuell nicht aktiv ist."}
