MultiLanguageSpellData['de'][1215707] = {name = "Paladinklassenset, Vergeltung, 11.1, 2 Teile", additional_info = "Ca. 10 Procs pro Minute\n[q]Eure Zauber und Fähigkeiten haben eine Chance, eine Siegesserie! zu aktivieren, die den Schaden von 'Urteil des Templers' und 'Göttlicher Sturm' um 2% erhöht und bis zu 10-mal stapelbar ist. 'Urteil des Templers' und 'Göttlicher Sturm' haben eine Chance von 12%, Eure Siegesserie! zu entfernen."}
MultiLanguageSpellData['de'][1215709] = {name = "Paladinklassenset, Vergeltung, 11.1, 4 Teile", additional_info = "[q]Wenn Ihr Eure Siegesserie! verliert, erhaltet Ihr die zuletzt verbrauchte Heilige Kraft zurück, könnt die nächsten 4.0 Sek. lang keine Heilige Kraft verlieren, und der Schaden Eurer Heilige Kraft verbrauchenden Fähigkeiten wird um 10% erhöht."}
