MultiLanguageSpellData['de'][1215730] = {name = "Jägerklassenset, Überleben, 11.1, 2 Teile", additional_info = "Ca. 10 Procs pro Minute\n[q]Eure Zauber und Fähigkeiten haben eine Chance, eine Siegesserie! zu aktivieren, die den Schaden von 'Lauffeuerbombe' um 3% erhöht und bis zu 6-mal stapelbar ist.\n 'Lauffeuerbombe' hat eine Chance von 15%, Eure Siegesserie! zu beenden.\n(Procchance: 15%)"}
MultiLanguageSpellData['de'][1215731] = {name = "Dämonenjägerklassenset, Verwüstung, 11.1, 2 Teile", additional_info = "Ca. 15 Procs pro Minute\n[q]Eure Zauber und Fähigkeiten haben eine Chance, eine Siegesserie! zu aktivieren, die den Schaden von 'Klingentanz' und 'Chaosstoß' um 3% erhöht und bis zu 10-mal stapelbar ist. 'Klingentanz' und 'Chaosstoß' haben eine Chance von 15%, Siegesserie! zu entfernen."}
MultiLanguageSpellData['de'][1215732] = {name = "Unvermeidbares Opfer", additional_info = "[q]Siegesserie! hält 8 Sek. lang an, nachdem sie durch 'Klingentanz' oder 'Chaosstoß' aufgehoben wurde.\n\n Beim Übergang in die Dämonengestalt werden alle Stapel von Siegesserie! geopfert, um pro verbrauchtem Stapel 2% kritische Trefferchance zu erlangen. Hält 15 Sek. lang an."}
MultiLanguageSpellData['de'][1215733] = {name = "Massenvernichtung", additional_info = "100 Meter Reichweite\nSofort\n[q]Eure Zauber und Fähigkeiten haben eine hohe Chance, Eure Gegner für ' Massenvernichtung ' zu markieren, was Meister Markieren-und-Verfolgen herbeiruft, der ( 2489 * 1 ) Feuerschaden verursacht, der zwischen Eurem Ziel und Gegnern in der Nähe aufgeteilt wird."}
MultiLanguageSpellData['de'][1215734] = {name = "Druidenklassenset, Wildheit, 11.1, 2 Teile", additional_info = "Ca. 10 Procs pro Minute\n[q]Eure Zauber und Fähigkeiten haben eine Chance, eine Siegesserie! zu aktivieren, die den Schaden von 'Wilder Biss', 'Zerfetzen' und 'Urzorn' um 3% erhöht und bis zu 10-mal stapelbar ist. 'Wilder Biss', 'Zerfetzen' und 'Urzorn' haben eine Chance von 15%, Siegesserie! zu entfernen. Kostenlose Einsätze von 'Wilder Biss' sind von dieser Chance ausgenommen."}
MultiLanguageSpellData['de'][1215735] = {name = "Druidenklassenset, Wildheit, 11.1, 4 Teile", additional_info = "[q]Wenn Ihr 'Gelüst des Eliteraubtiers' verbraucht, werdet Ihr zum 'Hauptgewinner!!!', wodurch dem Primärziel von 'Eliteraubtier' (1100% der Angriffskraft) körperlicher Schaden zugefügt wird und sich der Schaden Eurer regelmäßigen Effekte 6 Sek. lang um 16% erhöht."}
MultiLanguageSpellData['de'][1215738] = {name = "Verrottender Atem", additional_info = "50 Meter Reichweite\nWirken in 4 sek.\n[q]Der Zaubernde haucht verrottenden Atem auf Gegner vor sich und fügt allen getroffenen Spielercharakteren 9697798 Seuchenschaden zu."}
