MultiLanguageSpellData['de'][1215747] = {name = "Letzter Wille", additional_info = "100 Meter Reichweite\nSofort\n[q]Der letzte Wille des Kämpfers wird von den verbleibenden Wettstreitern absorbiert, was ihren verursachten Schaden um 10% erhöht und ihnen 35 zusätzliche Energie gewährt, nachdem sie ihre mächtigen Fähigkeiten eingesetzt haben. Dieser Effekt ist stapelbar."}
