MultiLanguageSpellData['de'][1218301] = {name = "Autobewerberprototyp", additional_info = "8 Meter Reichweite\nSofort 5 min Abklingzeit\n[q]Platziert den Autobewerber, der alle Kreaturen in der Nähe extrem anwidert, wodurch sie Euch 3 Min. lang 50% mehr Schaden zufügen.\n\n Kann nur in Lorenhall eingesetzt werden. Gegner lassen zusätzliche Marktforschung für den Zaubernden fallen, während dieser Effekt aktiv ist."}
MultiLanguageSpellData['de'][1218302] = {name = "Durchstechen", additional_info = "100 Meter Reichweite\nSofort\n[q]Giovantes stacheliger Körper durchsticht Euch und verursacht 12 Sek. lang alle 2 Sek. körperlichen Blutungsschaden. Dieser Effekt ist stapelbar."}
MultiLanguageSpellData['de'][1218303] = {name = "Schildgenerator", additional_info = nil}
MultiLanguageSpellData['de'][1218304] = {name = "Autobewerberprototyp", additional_info = "100 Meter Reichweite\nSofort\n[q]Platziert den Autobewerber, der alle Kreaturen in der Nähe extrem anwidert, wodurch sie Euch 3 Min. lang 50% mehr Schaden zufügen.\n\n Kann nur in Lorenhall eingesetzt werden. Gegner lassen zusätzliche Marktforschung für den Zaubernden fallen, während dieser Effekt aktiv ist."}
MultiLanguageSpellData['de'][1218305] = {name = "Leerengeschmiedeter Hengst", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Geschmiedet wie einst die Eisen an ihren Hufen, handelt es sich bei diesen Kreaturen nun weniger um Pferde sondern mehr um Leerenenergie in ihrer Gestalt.\"\nBeute:\nZone:\nVision von Sturmwind (Neuerlebt)"}
MultiLanguageSpellData['de'][1218306] = {name = "Leerenvernarbte Rudelmutter", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Im Kampf gegen ihre verdorbenen Halter konnte diese Rudelmutter sich und ihre Welpen befreien. Doch Freiheit von ihren Haltern bedeutete noch lange keine Freiheit von der Leere dieses verlorenen Ortes. Sie brachte ihren Welpen bei, zu noch gefährlicheren Bestien zu werden. Nun durchstreifen sie Orgrimmar auf der Suche nach Futter, während alle ums Überleben kämpfen.\"\nBeute:\nZone:\nVision von Orgrimmar (Neuerlebt)"}
MultiLanguageSpellData['de'][1218307] = {name = "Leerenvernarbter Windreiter", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Als die Leerenenergien entfesselt wurden, verfielen die meisten Windreiter in Raserei, wobei sie sich gegenseitig und ihre Ausbilder töteten. Die Tore zu ihrem Horst wurden von den Überlebenden verschlossen. Oben kann man noch einige der überlebenden Windreiter gleiten sehen, doch niemand traut sich, in ihr neues, tödliches Zuhause zurückzukehren, um zu sehen, was davon übrig ist.\"\nBeute:\nZone:\nVision von Orgrimmar (Neuerlebt)"}
MultiLanguageSpellData['de'][1218308] = {name = "Entzündendes Inferno", additional_info = "Sofort\n[q]Lohenzar entfesselt eine feurige Explosion auf jede gelöschte Kerze, entzündet sie wieder und fügt allen dabei getroffenen Spielercharakteren 8487876 Feuerschaden zu.\n\n Das Inferno versengt alle Spielercharaktere und fügt ihnen so 8 Sek. lang alle 1 Sek. 242445 Feuerschaden zu. Dieser Effekt ist stapelbar."}
MultiLanguageSpellData['de'][1218310] = {name = "Elektropunkturtestmodell", additional_info = "30 Meter ReichweiteWirken in 2 sek. 10 min Abklingzeit\n[q]Das Ziel wird von belebender Spannung durchströmt, was 3 Min. lang sein Tempo um 20% erhöht, den erlittenen Schaden um 25% verringert und es Naturschaden pulsieren lässt.\n\n Kann bei den meisten seltenen Kreaturen in Lorenhall eingesetzt werden. Ziele lassen zusätzliche Marktforschung für alle Spielercharaktere fallen, während dieser Effekt aktiv ist."}
MultiLanguageSpellData['de'][1218311] = {name = "Noggenfoggers Frischeauslese", additional_info = "{Sofort} {0.5 sek. Abklingzeit}\n[q]Wird vorübergehend kalt."}
