MultiLanguageSpellData['de'][1218314] = {name = "Ny'alothischer Schattenwurm", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren ny'alothischen Schattenwurm oder gibt ihn wieder frei.\n[q]\"Als Überrest der Vergangenheit des Schwarzen Imperiums kehren diese Vorläufer der Kluftwürmer mit dem Aufstieg von Ny'alotha wieder zurück.\"\nErfolg:\nMeister der VisionenKategorie:\nNeuerlebte Visionen von N'Zoth"}
MultiLanguageSpellData['de'][1218315] = {name = "Elektropunkturtestmodell", additional_info = "20 Meter Reichweite\nSofort\n[q]Verursacht 7 Naturschaden."}
MultiLanguageSpellData['de'][1218316] = {name = "Verderbnis der Aspekte", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört die Verderbnis der Aspekte oder gibt sie wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q]\"Mit N'Zoths Triumph wird das, was mit Galakrond begann, endlich Wirklichkeit. Und mit dem Verschwinden der Aspekte ist das Verderben ihrer Spezies vollbracht.\"\nVerkäufer:\nTorie\nZone:\nDornogal\nKosten:\n40.000"}
MultiLanguageSpellData['de'][1218317] = {name = "Leerenkristallpanther", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört einen reitbaren Leerenkristallpanther oder gibt ihn wieder frei.\n[q]\"Obwohl viele kostbare Edelsteine in verstörenden Visionen von den Leerenenergien verderbt wurden, können Juwelierskunstmeister sie immer noch verwenden, um mächtige Pantherrösser herzustellen.\"\nBeruf:\nJuwelierskunst"}
