MultiLanguageSpellData['de'][1222232] = {name = "Zorn des Verschlingers", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Adarus schleudert Kugeln aus gieriger Leere auf mehrere Positionen, die allen Spielercharakteren 5621532 kosmischen Schaden zufügen, wenn sie nicht abgefangen werden.\n\n Adarus fokussiert seinen Blick auf Spielercharaktere, die diese Kugeln abgefangen haben, greift sie kontinuierlich mit ' Verschlingen ' an und erhöht ihren erlittenen körperlichen Schaden um 100%.\n\n Bei Entfernung wird ' Zorn des Verschlingers ' auf einen Spielercharakter in der Nähe übertragen und fügt allen Spielercharakteren 2108075 kosmischen Schaden zu."}
MultiLanguageSpellData['de'][1222234] = {name = "Vantusrune: Lorenhall", additional_info = "Unbegrenzte Reichweite\nWirken in 1.5 sek.\n[q]Stellt Euch einmal pro Woche auf die Energien des anvisierten Schlachtzugsbosses aus Lorenhall ein und erlangt folgende Aura:\n\nVantusrune: Befreiung von Lorenhall\n Erhöht Eure Vielseitigkeit im Kampf gegen den entsprechenden Schlachtzugboss um 1500 . Der Effekt hält die ganze Woche lang an."}
MultiLanguageSpellData['de'][1222239] = {name = "Vantusrune: Lorenhall", additional_info = "Unbegrenzte Reichweite\nWirken in 1.5 sek.\n[q]Stellt Euch einmal pro Woche auf die Energien des anvisierten Schlachtzugsbosses aus Lorenhall ein und erlangt folgende Aura:\n\n Vantusrune: Befreiung von Lorenhall\n Erhöht Eure Vielseitigkeit im Kampf gegen den entsprechenden Schlachtzugboss um 1700 . Der Effekt hält die ganze Woche lang an."}
