MultiLanguageSpellData['de'][1222244] = {name = "Verschlingen", additional_info = "Unbegrenzte Reichweite\nWirken in 2 sek.\n[q]Adarus entzieht die Essenz aller Spielercharaktere, die derzeit von '' betroffen sind, verursacht 3 kosmischen Schaden und absorbiert die nächste 20 erhaltene Heilung.\n\n Dieser Ausbruch ruft ' Endloser Hunger ' hervor."}
MultiLanguageSpellData['de'][1222247] = {name = "Grässliches Gebrüll", additional_info = "Wirken in 2.5 sek.\n[q]Der Kriecher stößt ein Brüllen aus, fügt Spielercharakteren in der Nähe 10 Schattenschaden zu und erhöht den durch ' Grässliches Gebrüll ' erlittenen Schaden um 50%. Dieser Effekt ist stapelbar."}
MultiLanguageSpellData['de'][1222265] = {name = "Wilder Bund", additional_info = "Sofort\n[q]Der Meister und sein Tier werden von Wut erfüllt, wodurch sich ihr Angriffstempo 20 Sek. lang um 50% erhöht."}
MultiLanguageSpellData['de'][1222271] = {name = "Wyvernheulen", additional_info = "Sofort\n[q]Im Kampf beschwört Euer nächster 'Tötungsbefehl' alle 30 Sek. die Hilfe eines Wildtiers.\n\n Wyvern\n Ein Wyvern stürzt sich vom Himmel herab und stößt einen Kampfesschrei aus, der Euren Schaden sowie den Eurer Begleiter 15 Sek. lang um 10% erhöht.\n\n Eber\n Ein Eber stürmt 3-mal durch die gegnerischen Reihen und fügt dem Hauptziel (400% der Angriffskraft) körperlichen Schaden sowie bis zu 8 Gegnern in der Nähe (160% der Angriffskraft) Schaden zu.\n\n Bär\n Ein Bär stürzt sich ins Getümmel, reißt den Gegnern das Fleisch von den Knochen und fügt so bis zu 8 Gegnern in der Nähe im Verlauf von 10 Sek. (400% der Angriffskraft) Schaden zu."}
MultiLanguageSpellData['de'][1222275] = {name = "Hupen!", additional_info = "{Sofort} {1.5 sek. Abklingzeit}\n[q]Hupt, um allen zu zeigen, was Ihr gerade empfindet."}
MultiLanguageSpellData['de'][1222307] = {name = "Verschlingen", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Adarus entzieht die Essenz aller Spielercharaktere, die derzeit von '' betroffen sind, verursacht 3 kosmischen Schaden und absorbiert die nächste 2305797 erhaltene Heilung.\n\n Dieser Ausbruch ruft ' Endloser Hunger ' hervor."}
MultiLanguageSpellData['de'][1222310] = {name = "Endloser Hunger", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Adarus schwächt sein Ziel, wodurch der durch ' Verschlingen ' erlittene Schaden und die Heilungsabsorption 1 Min. lang um 20% erhöht werden. Dieser Effekt ist stapelbar."}
