MultiLanguageSpellData['de'][1229033] = {name = "Schwerkraftschmettern", additional_info = "12 Meter Reichweite\nWirken in 3.4 sek.\n[q]Drischt auf den Boden, um einen kleinen Leerenriss zu erzeugen. Fügt allen Gegnern innerhalb von 6 Metern um den Treffer Schattenschaden zu und zieht sie 6 Sek. lang dorthin."}
