MultiLanguageSpellData['de'][1233105] = {name = "Dunkle Rückstände", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Die stellaren Überreste brennen und verursachen 5 Sek. lang alle 1 Sek. 2023752 kosmischen Schaden. Dieser Effekt ist stapelbar."}
MultiLanguageSpellData['de'][1233109] = {name = "Hatarang", additional_info = "100 Meter Reichweite\nSofort\nCa. 2 Procs pro Minute\n[q]Brann hat eine Chance, zufällig ausgewählte Hüte hervorzuziehen und sie auf seine Gegner zu werfen, wodurch er mäßigen Schaden verursacht und 1 Schwächungseffekt auf 2 Ziele anwendet.\n\n Mögliche Schwächungseffekte sind eine Erhöhung des erlittenen Schadens um 20%, eine Verringerung des verursachten Schadens um 20% sowie eine Verringerung des Angriffs- und Zaubertempos um 20%.\n(20s Abklingzeit)"}
MultiLanguageSpellData['de'][1233110] = {name = "Läuternder Blitzschlag", additional_info = "300 Meter Reichweite\nSofort\n[q]Die Plexuswache kanalisiert durchgehend arkane Blitze durch sein Chassis, die allen Spielercharakteren mit jedem Wirken 386480 Arkanschaden zufügen. Jedes Wirken stärkt das Chassis, wodurch der Schaden nachfolgender Einsätze um 25% erhöht wird. Dieser Effekt ist stapelbar."}
