MultiLanguageSpellData['de'][1233511] = {name = "Umbralk'arroc", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Ein wilder K'arroc, der besonders gut darauf ausgelegt ist, das ewigwährende Zwielicht von K'aresh zu durchstreifen.\"\nErfolg:\nRuhm des Omegaschlachtzüglers\nKategorie:\nDungeons & Schlachtzüge"}
MultiLanguageSpellData['de'][1233515] = {name = "Dateninformationssicherungsbehältnis", additional_info = "[q]Eure Zauber und Fähigkeiten haben eine Chance, Euch in einen Blitzableiter zu verwandeln. Damit trefft Ihr 15 Sek. lang alle 3 Sek. ein zufälliges gegnerisches Ziel innerhalb von 40 Metern und fügt ihm ( 1 * 209 ) Naturschaden zu."}
MultiLanguageSpellData['de'][1233518] = {name = "Lavendelblauer K'arroc", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Der vorherige Halter dieses besonders streitlustigen K'arroc starb während einer Untersuchung des ungebundenen Raums. Vielleicht akzeptiert er ja Euch... Oder vielleicht auch nicht.\"\nVerkäufer:\nShad'anis\nZone:\nK'aresh\nKosten:\n10"}
