MultiLanguageSpellData['de'][1233539] = {name = "Verschlingen", additional_info = "Wirken in 2 sek.\n[q]Sobald er 100 Energie erreicht, erhöht Dimensius seine Dichte und erschafft eine mächtige, nach innen gerichtete Kraft, die 5 Sek. lang alle 1 Sek. 1686460 Schattenschaden verursacht und Spielercharaktere, Leerensterne, Schwarze Löcher und die Akkretionsscheibe hineinzieht.\n\n Nach 5 Sek. wird jeder Spielercharakter außerhalb von ' Gravitationsbrunnen ' eines Leerensterns sofort in Dimensius hineingesogen und fällt ins ' Auslöschung '."}
MultiLanguageSpellData['de'][1233542] = {name = "Der Knochengefrierer", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Dieser Kriecher ist ein erbitterter Rivale des Knochenschmelzers und wurde nach einer vernichtenden Niederlage aus seinem Versteck in der Manaschmiede Omega vertrieben. Jetzt will er von demjenigen lernen, der seinen größten Feind entthront hat.\"\nVandalen der Manaschmiede\nRuhmstufe:\n14\nOrt:\nSchattenpunkt"}
MultiLanguageSpellData['de'][1233544] = {name = "Erzählstundenteppich beschwören", additional_info = nil}
MultiLanguageSpellData['de'][1233546] = {name = "Rubinroter Leerenkrabbler", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Dieser Leerenkrabbler wurde vom Bund von K'aresh für Forschungszwecke \"gerettet\". Er hat sich als überaus robustes Reittier erwiesen.\"\nVerkäufer:\nOm'sirik\nZone:\nK'aresh\nKosten:\n8.125"}
MultiLanguageSpellData['de'][1233547] = {name = "Ätzender Leerenkrabbler", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Dieser Krabbler hat sich an giftigen Dünsten gelabt, wodurch sein Körper mit mächtigen Säuren angereichert wurde.\"\nVerkäufer:\nShad'anis\nZone:\nK'aresh\nKosten:\n7"}
