MultiLanguageSpellData['de'][1233553] = {name = "Unnachgiebiges Netherprisma", additional_info = "[q]Eure Fähigkeiten, die Schaden zufügen, ziehen fokussierte Leere aus dem Prisma, um ( 441 * 1 ) kosmischen Schaden zu verursachen, der zwischen Eurem Ziel und nahen Gegnern aufgeteilt wird. Der Schaden erhöht sich pro getroffenem Gegner um 30%, bis insgesamt 150%. Dieser Effekt kann alle 10 Sek. auftreten und sammelt bis zu 18 Mal die latente Macht innerhalb des Prismas.\n(10s Abklingzeit)"}
MultiLanguageSpellData['de'][1233556] = {name = "Unnachgiebiges Netherprisma", additional_info = "{Sofort} {20 sek. Abklingzeit}\n[q]Verbraucht sämtliche latente Macht, um 20 Sek. lang 18 Stärke oder Beweglichkeit pro Stapel zu erhalten."}
MultiLanguageSpellData['de'][1233557] = {name = "Dichte", additional_info = "Sofort\n[q]Erhöht den Schaden von 'Kosmische Strahlung' um 100%. Dieser Effekt ist stapelbar."}
MultiLanguageSpellData['de'][1233559] = {name = "Blauer Ingmar", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Eine besonders seltene Variante der Schieferrücken. Der \"Blaue Ingmar\" wurde zuvor beim Transport von Lasten eingesetzt.\"\nQuest:\nEuer Blauer\nZone:\nK'aresh"}
MultiLanguageSpellData['de'][1233561] = {name = "Neugieriger Schieferrücken", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Dieser neugierige Schieferrücken hat es irgendwie geschafft, in einer Kiste steckenzubleiben. Wie er es da überhaupt reingeschafft hat, ist noch nicht geklärt.\"\nBeute:\nZuckende Kiste des Gipfels\nZone:\nK'aresh"}
