MultiLanguageSpellData['de'][1233654] = {name = "Managetönte Brille", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Brann setzt während des Kampfes eine managetönte Brille auf, die alle 5 Sek. seinen verursachten Schaden um 4% und seinen erlittenen Schaden um 5% erhöht, bis zu 10-mal.\n\n Wird die Brille gebannt, heilt Brann sich um 40% seiner maximalen Gesundheit und betäubt Gegner in der Nähe für 3 Sek.\n Andernfalls wird dieser Effekt automatisch gebannt, wenn Branns Gesundheit unter 30% sinkt, wodurch die Betäubung verhindert wird."}
MultiLanguageSpellData['de'][1233655] = {name = "Managetönte Brille", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Brann setzt während des Kampfes eine managetönte Brille auf, die alle 5 Sek. seinen verursachten Schaden um 5% und seinen erlittenen Schaden um 5% erhöht, bis zu 10-mal.\n\n Wird die Brille gebannt, heilt Brann sich um 55% seiner maximalen Gesundheit und betäubt Gegner in der Nähe für 4 Sek.\n Andernfalls wird dieser Effekt automatisch gebannt, wenn Branns Gesundheit unter 30% sinkt, wodurch die Betäubung verhindert wird."}
MultiLanguageSpellData['de'][1233656] = {name = "Managetönte Brille", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Brann setzt während des Kampfes eine managetönte Brille auf, die alle 5 Sek. seinen verursachten Schaden um 5% und seinen erlittenen Schaden um 5% erhöht, bis zu 10-mal.\n\n Wird die Brille gebannt, heilt Brann sich um 70% seiner maximalen Gesundheit und betäubt Gegner in der Nähe für 5 Sek.\n Andernfalls wird dieser Effekt automatisch gebannt, wenn Branns Gesundheit unter 30% sinkt, wodurch die Betäubung verhindert wird."}
