MultiLanguageSpellData['de'][1233659] = {name = "Hatarang", additional_info = "100 Meter Reichweite\nSofort\nCa. 2 Procs pro Minute\n[q]Brann hat eine Chance, zufällig ausgewählte Hüte hervorzuziehen und sie auf seine Gegner zu werfen, wodurch er mäßigen Schaden verursacht und 1 Schwächungseffekt auf 3 Ziele anwendet.\n\n Mögliche Schwächungseffekte sind eine Erhöhung des erlittenen Schadens um 25%, eine Verringerung des verursachten Schadens um 25% sowie eine Verringerung des Angriffs- und Zaubertempos um 25%.\n(20s Abklingzeit)"}
MultiLanguageSpellData['de'][1233660] = {name = "Hatarang", additional_info = "100 Meter Reichweite\nSofort\nCa. 2 Procs pro Minute\n[q]Brann hat eine Chance, zufällig ausgewählte Hüte hervorzuziehen und sie auf seine Gegner zu werfen, wodurch er mäßigen Schaden verursacht und 2 Schwächungseffekt auf 4 Ziele anwendet.\n\n Mögliche Schwächungseffekte sind eine Erhöhung des erlittenen Schadens um 30%, eine Verringerung des verursachten Schadens um 30% sowie eine Verringerung des Angriffs- und Zaubertempos um 30%.\n(20s Abklingzeit)"}
