MultiLanguageSpellData['de'][1233693] = {name = "Sande von K'aresh", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Wenn Brann ' Sammelwerkzeuge ' einsetzt, beginnen Sande um die Gruppenmitglieder zu wirbeln, gewähren bis zu 10-mal 8% kritischen Trefferwert und verlangsamen Gegner in der Nähe um 8%.\n\n Ein kritischer Treffer erschafft 6 Sek. lang einen Sandteufel am Ort des Ziels, der Gegner periodisch in sein Zentrum zieht. Kann nur alle 45 Sek. auftreten.\n\n Sammelwerkzeuge\nBrann setzt seine Sammelwerkzeuge ein, um Spielercharakteren zu helfen, zusätzliches Gold, Erz, Leder, zusätzliche Kräuter, Fische und Schätze zu finden."}
MultiLanguageSpellData['de'][1233694] = {name = "Sande von K'aresh", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Wenn Brann ' Sammelwerkzeuge ' einsetzt, beginnen Sande um die Gruppenmitglieder zu wirbeln, gewähren bis zu 10-mal 10% kritischen Trefferwert und verlangsamen Gegner in der Nähe um 10%.\n\n Ein kritischer Treffer erschafft 6 Sek. lang einen Sandteufel am Ort des Ziels, der Gegner periodisch in sein Zentrum zieht. Kann nur alle 45 Sek. auftreten.\n\n Sammelwerkzeuge\nBrann setzt seine Sammelwerkzeuge ein, um Spielercharakteren zu helfen, zusätzliches Gold, Erz, Leder, zusätzliche Kräuter, Fische und Schätze zu finden."}
MultiLanguageSpellData['de'][1233695] = {name = "Sande von K'aresh", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Wenn Brann ' Sammelwerkzeuge ' einsetzt, beginnen Sande um die Gruppenmitglieder zu wirbeln, gewähren bis zu 10-mal 12% kritischen Trefferwert und verlangsamen Gegner in der Nähe um 12%.\n\n Ein kritischer Treffer erschafft 6 Sek. lang einen Sandteufel am Ort des Ziels, der Gegner periodisch in sein Zentrum zieht. Kann nur alle 45 Sek. auftreten.\n\n Sammelwerkzeuge\nBrann setzt seine Sammelwerkzeuge ein, um Spielercharakteren zu helfen, zusätzliches Gold, Erz, Leder, zusätzliche Kräuter, Fische und Schätze zu finden."}
MultiLanguageSpellData['de'][1233699] = {name = "Äthernova", additional_info = "100 Meter Reichweite\nSofort\n[q]Wenn die Gesundheit eines Gruppenmitglieds unter 60 % sinkt, materialisiert sich ein astraler Energieumwandler, der Gegnern in der Nähe moderaten Schaden zufügt und diese 4 Sek. lang verspottet. Nach Ablauf des Spotts entfesselt der Umwandler eine Ätherwelle, die Verbündete in der Nähe um 30 % ihrer Gesundheit heilt. Kann alle 2 Min. ausgelöst werden. Das Töten von Gegnern reduziert die Abklingzeit dieses Effekts um 4 Sek."}
MultiLanguageSpellData['de'][1233700] = {name = "Äthernova", additional_info = "100 Meter Reichweite\nSofort\n[q]Wenn die Gesundheit eines Gruppenmitglieds unter 60 % sinkt, materialisiert sich ein astraler Energieumwandler, der Gegnern in der Nähe moderaten Schaden zufügt und diese 6 Sek. lang verspottet. Nach Ablauf des Spotts entfesselt der Umwandler eine Ätherwelle, die Verbündete in der Nähe um 40 % ihrer Gesundheit heilt. Kann alle 2 Min. ausgelöst werden. Das Töten von Gegnern reduziert die Abklingzeit dieses Effekts um 6 Sek."}
