MultiLanguageSpellData['de'][1233896] = {name = "Ramponierte Aegis", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Während die Aegis ausgerüstet ist, verursachen alle Gruppenmitglieder 6% mehr Schaden und Heilung. Im Kampf heilt Ihr und Brann alle 10 Sek. um 10% des Schadens, den Ihr in dieser Zeit erlitten habt.\n\n Stirbt ein Spielercharakter, gewährt die Aegis diesem bei der Wiederbelebung 2% Schadensverringerung und 3% erhöhte Heilung, reduziert jedoch seinen verursachten Schaden und die Heilung um 2%. Dieser Effekt ist bis zu 3-mal stapelbar."}
MultiLanguageSpellData['de'][1233897] = {name = "Temporalentschleunigungskristall", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Wenn Ihr einem Elitegegner mit 80% oder mehr sowie mit 20% oder weniger Gesundheit Schaden zufügt, löst Brann die Energien des Kristalls aus. Dies verringert das Angriffs- und Zaubertempo des Elitegegners 30 Sek. lang um 30%. Wird der betroffene Elitegegner getötet, während der Schwächungseffekt aktiv ist, erhält die Gruppe eine stapelbare Tempostärkung von 4%."}
MultiLanguageSpellData['de'][1233898] = {name = "Sonderbares Gerät", additional_info = "Unbegrenzte Reichweite\nSofort\nCa. 2 Procs pro Minute\n[q]Brann hat eine Chance, Spielercharakteren 20 Sek. lang und basierend auf seiner gewählten Kampfrolle einen Bonus von 10% auf Gesundheit, Schaden oder Heilung zu gewähren.\n\n Spielercharaktere haben eine Chance, Brann 20 Sek. lang und basierend auf ihrer gewählten Rolle einen Bonus von 10% auf Gesundheit, Schaden oder Heilung zu gewähren.\n(20s Abklingzeit)"}
