MultiLanguageSpellData['de'][1235371] = {name = "Frostfieber", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Eine Krankheit, die im Verlauf von 30 Sek. [(214% der Angriffskraft) * [(Angriffskraft * 0.98)][((Angriffskraft + Schildhand-Angriffskraft) * 2 / 3)] -- 2H, DW / Angriffskraft] Frostschaden verursacht und jedes Mal, wenn sie Schaden verursacht, eine Chance hat, dem Todesritter 4 Runenmacht zu gewähren."}
MultiLanguageSpellData['de'][1235372] = {name = "Blutseuche", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Eine schattenhafte Krankheit, die dem Ziel im Verlauf von 30 Sek. 100 Gesundheit entzieht."}
MultiLanguageSpellData['de'][1235382] = {name = "Bevorstehender Sieg", additional_info = "Nahkampfreichweite\nSofort\n[q]Greift das Ziel sofort an, verursacht 30846 Schaden und heilt Euch um 30% Eurer maximalen Gesundheit.\n\n Nach dem Töten eines Gegners, der Erfahrung oder Ehre gewährt, wird die Abklingzeit von 'Bevorstehender Sieg' abgeschlossen und die Fähigkeit kostet keine Wut."}
