MultiLanguageSpellData['de'][1235934] = {name = "Hammer des Lichts", additional_info = "100 Meter Reichweite\nSofort\n[q]Hämmert mit der Macht des Lichts auf Euren Gegner ein, was diesem (580.645% der Angriffskraft) Heiligschaden und bis zu 4 Gegnern in der Nähe (290% der Angriffskraft) Heiligschaden zufügt.\n\n Ruft außerdem Himmelshämmer herab, die 3 Gegner in der Nähe treffen und ihnen jeweils (46.55% der Angriffskraft) Heiligschaden zufügen."}
MultiLanguageSpellData['de'][1235946] = {name = "Mal des unablässigen Zorns", additional_info = "Sofort\n[q]Wenn Ihr Schaden erleidet, werdet Ihr erzürnt, wodurch Ihr 202 Schaden absorbiert und 461 Schattenschaden pro Erzürnung verursacht, der auf Gegner in der Nähe aufgeteilt wird. Schaden pro zusätzlichem Gegner um 30% erhöht, bis maximal 150%.\n\n Ihr könnt alle 15 Sek. erneut erzürnt gemacht werden, bis zu 15 Stapeln, beruhigt Euch nach Ende des Kampfes aber schnell.\n\nGilt nur für Tankspezialisierungen."}
MultiLanguageSpellData['de'][1235959] = {name = "Mage Spellslinger 11.2 Class Set 2pc", additional_info = "[q]Arkan\n Schaden von 'Arkanschlag' um 12% erhöht, und 'Arkanschlag' gewährt 1 Stapel von 'Arkane Harmonie'. Direkter 'Splitter'-Schaden gewährt mit einer Chance von 25% einen Stapel 'Arkane Harmonie'.\n\nFeuer, Frost\n Schaden von 'Eislanze' und 'Eiszapfen' um 10% erhöht, und 'Eislanze' hat eine Chance von 50%, 1 Stapel von 'Kaltfront' zu gewähren. Direkter 'Splitter'-Schaden gewährt mit einer Chance von 15% einen Stapel 'Kaltfront'."}
MultiLanguageSpellData['de'][1235962] = {name = "Mage Sunfury 11.2 Class Set 2pc", additional_info = "[q]Arkan, Feuer, Frost\n Der Zauberschadensbonus von 'Zauberfeuersphäre' ist um 1.0% erhöht. 'Manakaskade' gewährt nun zusätzlich 0.5% Tempo pro Stapel."}
MultiLanguageSpellData['de'][1235963] = {name = "Mage Frostfire 11.2 Class Set 2pc", additional_info = "[q]Feuer\n Der Schaden von 'Kometenhagel' und 'Frostfeuerausstoß' wird um 15% erhöht. Der Schaden von 'Frostfeuerblitz' wird um 8% erhöht. 'Kometenhagel', 'Frostfeuerausstoß' und 'Frostfeuerblitz' verursachen jetzt 'Entzünden' mit 75% Effektivität.\n\nArkan, Frost\n Der Schaden von 'Meteor' und 'Frostfeuerausstoß' wird um 30% erhöht. Der Schaden von 'Frostfeuerblitz' wird um 10% erhöht. 'Meteor', 'Frostfeuerausstoß' und 'Frostfeuerblitz' verursachen jetzt 'Entzünden', wodurch zusätzlich 9 Sek. lang 25 Schaden verursacht wird."}
MultiLanguageSpellData['de'][1235964] = {name = "Mage Spellslinger 11.2 Class Set 4pc", additional_info = "[q]Arkan\n Splitterschaden um 8% erhöht. 'Arkane Kugel' gewährt mit einer Chance von 100% bis zu 8-mal einen Stapel 'Arkane Harmonie'. Bei Erreichen von 20 Stapeln 'Arkane Harmonie' erhaltet Ihr 'Intuition' zu 100% Effektivität. lang um 8%.\n\nFeuer\n Splitterschaden um 8% erhöht. 'Arkane Kugel' gewährt mit einer Chance von 100% bis zu 8-mal einen Stapel 'Arkane Harmonie'. Wenn 'Kaltfront' eine 'Gefrorene Kugel' beschwört, erhöht sich Euer Zauberschaden 10 Sek. lang um 8%.\n\nFrost\n Wenn 'Gefrorene Kugel' mindestens einem Gegner Schaden zufügt, gewährt sie mit einer Chance von 15% einen Stapel 'Kaltfront'.. Wenn 'Kaltfront' eine 'Gefrorene Kugel' beschwört, erhöht sich Euer Zauberschaden 10 Sek. lang um 8%.\n\n(100ms Abklingzeit)"}
MultiLanguageSpellData['de'][1235965] = {name = "Mage Sunfury 11.2 Class Set 4pc", additional_info = "[q]Arkan\n Außergewöhnliche Zauber, die von Eurem Phönix gewirkt werden, verlängern die Dauer Eures nächsten Einsatzes von 'Arkane Seele' um 0.5 Sek. Wenn Euer Phönix vergeht, ermächtigt er Euch noch weiter und verleiht Euch 10 Sek. lang eine geringe 'Zeitkrümmung' und 20% erhöhten Zauberschaden.\n\nFeuer, Frost\n Außergewöhnliche Zauber, die von Eurem Phönix gewirkt werden, verlängern die Dauer Eures nächsten Einsatzes von 'Hyperthermie' um 0.3 Sek. Wenn Euer Phönix vergeht, ermächtigt er Euch noch weiter und verleiht Euch 10 Sek. lang eine geringe 'Zeitkrümmung' und 10% erhöhten Zauberschaden."}
MultiLanguageSpellData['de'][1235966] = {name = "Mage Frostfire 11.2 Class Set 4pc", additional_info = "[q]Arkan, Frost\n Der Einsatz von 'Gletscherstachel' hat eine Chance von 100%, außerdem einen einen 'Pyroschlag' zu wirken, der (352.5% der Zaubermacht) Feuerschaden verursacht. Außerdem profitiert 'Pyroschlag' jetzt von 'Entzünden'.\n\nFeuer\n Der Einsatz von 'Pyroschlag' hat eine Chance von 20%, außerdem einen 'Gletscherstachel' zu wirken, der (366.24% der Zaubermacht) Frostschaden verursacht. Durch diesen Effekt gewirkte 'Gletscherstachel' verwurzeln nicht. Außerdem profitiert 'Gletscherstachel' jetzt von 'Entzünden'."}
