MultiLanguageSpellData['de'][1235985] = {name = "Vertrag: Der Bund von K'aresh", additional_info = "Sofort\n[q]Unterzeichnet einen Vertrag mit dem Bund von K'aresh, der Euch bis zur wöchentlichen Zurücksetzung jedes Mal 5 Ruf bei dieser Fraktion gewährt, wenn Ihr eine Weltquest in Khaz Algar abschließt.\n\n Kriegsmeutenvertrag\n Ihr könnt pro Woche nur einen Vertrag unterzeichnen. Dieser Effekt gilt für Eure gesamte Kriegsmeute."}
