MultiLanguageSpellData['de'][1236126] = {name = "Bindender Wurfspeer", additional_info = "100 Meter Reichweite\nSofort\n[q]Taah'bat schleudert arkane Speere auf anvisierte Spielercharaktere, fügt Spielercharakteren innerhalb von 8 Metern um die Ziele 2424449 Arkanschaden zu und fesselt alle getroffenen Spielercharaktere.\n\n Jede Fessel verursacht alle 1 Sek. 606112 Arkanschaden und verringert die Bewegungsgeschwindigkeit um 50%. Die Wirkung verstärkt sich alle 5 Sek., bis der Speer zerstört wird. Dieser Effekt ist stapelbar."}
MultiLanguageSpellData['de'][1236127] = {name = "Seelenausstoß", additional_info = "30 Meter Reichweite\nSofort\n[q]Die entfesselte Seele entschwindet beim Sterben rasch in die Leere und fügt Spielercharakteren innerhalb von 30 Metern 2 Arkanschaden zu."}
MultiLanguageSpellData['de'][1236128] = {name = "Statische Aufladung", additional_info = "[q]Eure Zauber und Fähigkeiten haben eine Chance, Euch 'Statische Aufladung' zu gewähren, die Eure Vielseitigkeit 30 Sek. lang um ( 17 * 20) erhöht. Jeder Eurer nächsten Einsätze von Zaubern und Fähigkeiten verringert den Vielseitigkeitsbonus um 5%."}
MultiLanguageSpellData['de'][1236129] = {name = "Elektrische Ladung", additional_info = "[q]Ihr erlangt zu Kampfbeginn 'Elektrische Ladung', die Eure Meisterschaft alle 2 Sek. um 10 erhöht, bis maximal (12 * 10 ). Nach 24 Sek. fällt der Zyklus wieder ab und wiederholt sich."}
MultiLanguageSpellData['de'][1236130] = {name = "Bindender Wurfspeer", additional_info = "100 Meter Reichweite\nWirken in 3 sek.\n[q]Taah'bat schleudert arkane Speere auf anvisierte Spielercharaktere, fügt Spielercharakteren innerhalb von 8 Metern um die Ziele 2424449 Arkanschaden zu und fesselt alle getroffenen Spielercharaktere.\n\n Jede Fessel verursacht alle 1 Sek. 606112 Arkanschaden und verringert die Bewegungsgeschwindigkeit um 50%. Die Wirkung verstärkt sich alle 5 Sek., bis der Speer zerstört wird. Dieser Effekt ist stapelbar."}
MultiLanguageSpellData['de'][1236132] = {name = "Aufgeladene Berührung", additional_info = "[q]Eure Heilzauber haben eine Chance, auf das Ziel mit der geringsten Gesundheit innerhalb von 40 Metern überzuspringen und es um 1766 Gesundheit zu heilen."}
