MultiLanguageSpellData['de'][1236254] = {name = "Death Knight Deathbringer 11.2 Class Set 4pc", additional_info = "[q]Blut, Frost, Unheilig\n 'Exterminieren' verursacht 20% mehr Schaden und 'Mal des Schnitters' ist bis zu 15-mal zusätzlich stapelbar. Wenn es explodiert, erhöht 'Mal des Schnitters' Eure kritische Trefferchance 8 Sek. lang um 10%.\n(1s Abklingzeit)"}
MultiLanguageSpellData['de'][1236256] = {name = "Vorpalspalten", additional_info = "10 Meter Reichweite\nWirken in 2.5 sek.\n[q]Der Zaubernde spaltet den Bereich vor ihm, verursacht Schattenschaden und belegt getroffene Spielercharaktere mit einem Heilungsabsorptionsschild."}
MultiLanguageSpellData['de'][1236259] = {name = "Death Knight San'layn 11.2 Class Set 2pc", additional_info = "[q]Unheilig\n Der Einsatz von 'Kummer bereiten' verlängert die Dauer Eurer Krankheit auf Eurem Primärziel um zusätzliche 3.0 Sek. und 'Essenz der Blutkönigin' erhöht Eure Meisterschaft zusätzlich um 0.5% pro Stapel.\n\nBlut, Frost\n Der Einsatz von 'Kummer bereiten' verlängert die Dauer Eurer Krankheit auf Eurem Primärziel um zusätzliche 4.0 Sek. und 'Essenz der Blutkönigin' erhöht Eure Meisterschaft zusätzlich um 0.5% pro Stapel."}
MultiLanguageSpellData['de'][1236260] = {name = "Death Knight San'layn 11.2 Class Set 4pc", additional_info = "[q]Unheilig\n Eure Fähigkeit 'Kummer bereiten' verursacht 30% mehr Schaden und der Einsatz von 'Vampirstoß' erhöht den Schaden Eurer nächsten Einsätze von Ghule 8 Sek. lang um 20%. Mehrere Anwendungen können sich überlappen.\n\nBlut, Frost\n Eure Fähigkeit 'Kummer bereiten' verursacht 50% mehr Schaden und der Einsatz von 'Vampirstoß' erhöht den Schaden Eurer nächsten Einsätze von Tanzende Runenwaffen 8 Sek. lang um 20%. Mehrere Anwendungen können sich überlappen."}
MultiLanguageSpellData['de'][1236262] = {name = "Shaohaos Weisenschlange", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Die Lektionen, die Shaohao während seiner Lebzeiten und im Tod gelernt und die Leidenschaft, die er für seine Heimat verspürt hat, haben sich zu dieser ätherischen Schlange verschmolzen: eine Reflektion der Weisheit des Kaisers.\"\nPromotion:\nMists of Pandaria Classic"}
MultiLanguageSpellData['de'][1236263] = {name = "Arkanes Schocken", additional_info = "30 Meter Reichweite\nWirken in 1.75 sek.\n[q]Inflicts 5 Arcane damage to an enemy."}
MultiLanguageSpellData['de'][1236272] = {name = "Kritische Kette", additional_info = "Sofort\nCa. 1.5 Procs pro Minute\n[q]Eure Zauber und Fähigkeiten haben eine Chance, 'Kritische Überladung' auszulösen, die Euren kritischen Trefferwert 20 Sek. lang alle 2 Sek. um 39 erhöht.\n(20s Abklingzeit)"}
MultiLanguageSpellData['de'][1236273] = {name = "Funkenexplosion", additional_info = "Sofort\nCa. 1.5 Procs pro Minute\n[q]Eure Zauber und Fähigkeiten haben eine Chance, eine Funkenexplosion auszulösen, die Euer Tempo 20 Sek. lang um 174 erhöht."}
MultiLanguageSpellData['de'][1236275] = {name = "Statische Aufladung", additional_info = "Sofort\nCa. 1.5 Procs pro Minute\n[q]Eure Zauber und Fähigkeiten haben eine Chance, Euch 'Statische Aufladung' zu gewähren, die Eure Vielseitigkeit 30 Sek. lang um ( 17 * 20) erhöht. Jeder Eurer nächsten Einsätze von Zaubern und Fähigkeiten verringert den Vielseitigkeitsbonus um 5%.\n(29s Abklingzeit)"}
MultiLanguageSpellData['de'][1236276] = {name = "Elektrische Ladung", additional_info = "Sofort\n[q]Ihr erlangt zu Kampfbeginn 'Elektrische Ladung', die Eure Meisterschaft alle 2 Sek. um 10 erhöht, bis maximal (12 * 10 ). Nach 24 Sek. fällt der Zyklus wieder ab und wiederholt sich."}
MultiLanguageSpellData['de'][1236277] = {name = "Aufgeladene Berührung", additional_info = "Sofort\nCa. 2 Procs pro Minute\n[q]Eure Heilzauber haben eine Chance, auf das Ziel mit der geringsten Gesundheit innerhalb von 40 Metern überzuspringen und es um 1766 Gesundheit zu heilen."}
MultiLanguageSpellData['de'][1236278] = {name = "Energieschild", additional_info = "Sofort\nCa. 1.5 Procs pro Minute\n[q]Wenn Ihr Schaden erleidet, habt Ihr eine Chance, einen titanischen Energieschild zu erlangen, der 10 Sek. lang bis zu 3662 Schaden aufhebt. Wenn der Schild abläuft, verursacht er 30% der verbleibenden Absorption als Arkanschaden, aufgeteilt auf Gegner innerhalb von 8 Metern."}
MultiLanguageSpellData['de'][1236279] = {name = "Aufgeladener Kristall", additional_info = "Sofort\nCa. 1.5 Procs pro Minute\n[q]Eure Zauber und Angriffe haben eine Chance, 'Geladener Blitz' auf Euer Ziel niedergehen zu lassen, was 1206 Naturschaden verursacht, aufgeteilt auf Ziele innerhalb von 8 Metern."}
