MultiLanguageSpellData['de'][1236330] = {name = "Druid Druid of the Claw 11.2 Class Set 4pc", additional_info = "[q]Wildheit\n Beim Einsatz von 'Verheeren' besteht eine Chance von 40%, dass Ihr Euer Ziel 4 Sek. später mit 100% Effektivität erneut verheert.\n\nGleichgewicht, Wächter, Wiederherstellung\n Beim Einsatz von 'Verheeren' besteht eine Chance von 40%, dass Ihr Euer Ziel 4 Sek. später mit 60% Effektivität erneut verheert."}
MultiLanguageSpellData['de'][1236331] = {name = "Druid Druid of the Claw 11.2 Class Set 2pc", additional_info = "[q]Der Einsatz von 'Verheeren' erhöht 5 Sek. lang Euer Tempo um 10%, Eure kritische Trefferchance um 10% und Euren verursachten Blutungsschaden um 30%.\n(100ms Abklingzeit)"}
MultiLanguageSpellData['de'][1236332] = {name = "Druid Elune's Chosen 11.2 Class Set 2pc", additional_info = "[q]Wildheit, Wächter, Wiederherstellung\n Der Schaden von 'Hauen' ist um 20% erhöht. Beim Einsatz von 'Hauen' besteht eine Chance von 40%, dass ein 'Sternensog' mit 160% Effektivität gegen einen Gegner ausgelöst wird.\n\nGleichgewicht\n Der Schaden von 'Sternenfeuer' ist um 20% erhöht. Wenn Ihr Astrale Macht durch 'Sternenfeuer' erhaltet, besteht eine Chance von 40%, dass ein 'Sternensog' mit 45% Effektivität gegen einen Gegner ausgelöst wird.\n\n(100ms Abklingzeit)"}
MultiLanguageSpellData['de'][1236333] = {name = "Druid Elune's Chosen 11.2 Class Set 4pc", additional_info = "[q]Wildheit, Wächter, Wiederherstellung\n Ein 'Sternensog', der durch 'Hauen' ausgelöst wurde, spaltet sich beim Einschlag mit 20% Effektivität auf bis zu 3 zusätzliche Ziele auf und erzeugt einen Stapel von 'Mondlicht sammeln'. Der Einsatz von 'Mondstrahl' verbraucht 'Mondlicht sammeln', um Euren Schaden 12 Sek. lang um 4% pro Stapel zu erhöhen.\n\nGleichgewicht\n Ein 'Sternensog', der durch 'Sternenfeuer' ausgelöst wurde, spaltet sich beim Einschlag mit 40% Effektivität auf bis zu 3 zusätzliche Ziele auf und erzeugt einen Stapel von 'Mondlicht sammeln'. Der Einsatz von 'Zorn der Elune' oder 'Vollmond' verbraucht 'Mondlicht sammeln', um Euren Schaden 12 Sek. lang um 4% pro Stapel zu erhöhen."}
MultiLanguageSpellData['de'][1236334] = {name = "Druid Keeper of the Grove 11.2 Class Set 2pc", additional_info = "[q]Gleichgewicht, Wildheit, Wächter\n Der Einsatz von 'Himmlische Ausrichtung' erbittet für 10 Sek. die Unterstützung einer Dryade, die 'Sternensog' mit 360% Effektivität' und 'Sternenregen' mit 800% Effektivität wirkt.\n\nWiederherstellung\n Der Einsatz von 'Inkarnation: Baum des Lebens' oder 'Konvokation der Geister' erbittet für 5 Sek. die Unterstützung einer Dryade, die 'Gelassenheit' mit 50% Effektivität wirkt und Euren Verbündeten mit der niedrigsten Gesundheit sofort mit 200% Effektivität 'Nachwachsen' lässt."}
MultiLanguageSpellData['de'][1236336] = {name = "Druid Keeper of the Grove 11.2 Class Set 4pc", additional_info = "[q]Wiederherstellung\n Wenn Eure Dryade vergeht, verursachen Eure nächsten 2 Einsätze von 'Rasche Heilung' zusätzliche Heilung in Höhe von 5% der verursachten Heilung, während sie aktiv war, und 25% der Heilung greift auf Verbündete in der Nähe über. Wird nach dem 5. Ziel reduziert.\n\nGleichgewicht, Wildheit, Wächter\n Wenn Eure Dryade vergeht, verursachen Eure nächsten 2 Einsätze von 'Sternensog' zusätzlichen Schaden in Höhe von 3% des verursachten Schadens, während sie aktiv war, und 10% des Schadens greift auf Gegner in der Nähe über. Wird nach dem 5. Ziel reduziert."}
MultiLanguageSpellData['de'][1236337] = {name = "Druid Wildstalker 11.2 Class Set 2pc", additional_info = "[q]Wildheit\n Die Wachstumsrate von 'Blutsucherranken' ist um 40% erhöht.Der Einsatz von $?c2['Tigerfuror' lässt 'Blutsucherranken' auf bis zu 3 verfügbare Gegner in der Nähe übergreifen.\n\nGleichgewicht, Wächter, Wiederherstellung\n Die Wachstumsrate von 'Symbiotische Blüte' ist um 45% erhöht.'Nachwachsen' mit 'Freizaubern' lässt 'Symbiotische Blüte' auf bis zu 2 verfügbare Verbündete in der Nähe übergreifen."}
MultiLanguageSpellData['de'][1236338] = {name = "Druid Wildstalker 11.2 Class Set 4pc", additional_info = "[q]Wildheit\n Beim Einsatz von 'Blutsucherranken' besteht alle 2 Sek. eine Chance von 20%, dass 'Berstender Wuchs' mit 100% Effektivität ausgelöst wird. Jeder Stapel von 'Blutsucherranken' auf einem Gegner erhöht den Schaden durch 'Berstender Wuchs' um 40%.\n\nGleichgewicht, Wächter, Wiederherstellung\n Beim Einsatz von 'Symbiotische Blüte' besteht alle 2 Sek. eine Chance von 35%, dass 'Berstender Wuchs' mit 100% Effektivität ausgelöst wird. Jeder Stapel von 'Symbiotische Blüte' auf einem Verbündeten erhöht die Heilung durch 'Berstender Wuchs' um 30%."}
MultiLanguageSpellData['de'][1236342] = {name = "Angriffsvorbereitung", additional_info = "Sofort\n[q]Wildheit\nBeim Einsatz von 'Verheeren' besteht eine Chance von 40%, dass Ihr Euer Ziel 4 Sek. später mit 100% Effektivität erneut verheert.\n\nGleichgewicht, Wächter, Wiederherstellung\nBeim Einsatz von 'Verheeren' besteht eine Chance von 40%, dass Ihr Euer Ziel 4 Sek. später mit 60% Effektivität erneut verheert."}
