MultiLanguageSpellData['de'][1236348] = {name = "Aufgeladenes Schlitzen", additional_info = "100 Meter Reichweite\n{Wirken in} {4 sek. 3 sek. Abklingzeit}\n[q]Zo'phex lädt sein Schwert auf und führt einen massiven Hieb, der allen Gegnern vor ihm 15758921 körperlichen Schaden zufügt."}
MultiLanguageSpellData['de'][1236350] = {name = "Void Power Shard Released Visuals - COSMETIC", additional_info = nil}
MultiLanguageSpellData['de'][1236354] = {name = "Seelensauger", additional_info = "40 Meter Reichweite\n{Wirken in} {2 sek. 5 sek. Abklingzeit}\n[q]Der Zaubernde verlangsamt sein Ziel und entzieht ihm im Verlauf von 8 Sek. insgesamt 622547 Gesundheit. Der Zaubernde wird um das Doppelte des entzogenen Betrags geheilt."}
MultiLanguageSpellData['de'][1236355] = {name = "Death Knight Rider of the Apocalypse 11.2 Class Set 2pc", additional_info = "[q]Blut, Unheilig\n Der Einsatz von 'Apokalypse' beschwört jetzt Weißsträhne für 10 Sek. 'Weißsträhnes Untod' verursacht 20% mehr Schaden und infiziert bei Ausbreitung 1 zusätzliche Ziele, und ihr 'Todesmantel' verursacht 35% mehr Schaden.\n\nFrost\n Der Einsatz von Säule des Frosts beschwört jetzt Trollbann für 10 Sek. 'Trollbanns eisiger Zorn' verursacht 20% mehr Schaden und sein 'Auslöschen' verursacht 15% mehr Schaden."}
MultiLanguageSpellData['de'][1236356] = {name = "Death Knight Rider of the Apocalypse 11.2 Class Set 4pc", additional_info = "[q]Frost\n Der Einsatz von 'Auslöschen' oder 'Frostsichel' befiehlt Trollbann, ebenfalls 'Auslöschen' oder 'Frostsichel' mit 100% Effektivität einzusetzen. Euer 'Auslöschen' verursacht 20% mehr Schaden gegen Ziele, die von 'Trollbanns eisiger Zorn' betroffen sind.\n\nBlut, Unheilig\n Der Einsatz von 'Todesmantel' oder 'Epidemie' befiehlt Weißsträhne, ebenfalls 'Todesmantel' oder 'Epidemie' mit 125% Effektivität einzusetzen. Euer 'Todesmantel' verursacht 40% mehr Schaden gegen Ziele, die von 'Weißsträhnes Untod' betroffen sind.\n\n(500ms Abklingzeit)"}
MultiLanguageSpellData['de'][1236358] = {name = "Demon Hunter Aldrachi Reaver 11.2 Class Set 2pc", additional_info = "[q]Der Schaden von 'Gleve des Reißers' ist um 50% erhöht und anderer rein körperlicher Schaden ist um 25% erhöht."}
MultiLanguageSpellData['de'][1236360] = {name = "Demon Hunter Aldrachi Reaver 11.2 Class Set 4pc", additional_info = "[q]Verwüstung\n Der Einsatz von 'Wut der Aldrachi' ermächtigt den Einsatz von 'Klingentanz' im Anschluss an 'Chaosstoß' weiter, was die Anzahl der Schnitte auf 12 erhöht.\n\n 'Mal des Reißers' ist jetzt bis zu 2-mal stapelbar und ermächtigt den Einsatz von 'Chaosstoß' im Anschluss an 'Klingentanz' weiter, was einen zusätzlichen Stapel für 100% der normalen Dauer erzeugt.\n\nRachsucht\n Der Einsatz von 'Wut der Aldrachi' ermächtigt den Einsatz von 'Seelenspalter' im Anschluss an 'Abscheren' weiter, was die Anzahl der Schnitte auf 12 erhöht.\n\n 'Mal des Reißers' ist jetzt bis zu 2-mal stapelbar und ermächtigt den Einsatz von 'Abscheren' im Anschluss an 'Seelenspalter' weiter, was einen zusätzlichen Stapel für 100% der normalen Dauer erzeugt."}
MultiLanguageSpellData['de'][1236361] = {name = "Demon Hunter Fel-Scarred 11.2 Class Set 2pc", additional_info = "[q]Verwüstung\n Der Einsatz von 'Feuerbrandaura' verursacht 30% mehr Schaden und erhöht den Schaden von 'Chaosstoß' während der aktiven Dauer um 20%.\n\nRachsucht\n Der Einsatz von 'Feuerbrandaura' verursacht 30% mehr Schaden und erhöht den Schaden von 'Seelenspalter' während der aktiven Dauer um 20%."}
MultiLanguageSpellData['de'][1236362] = {name = "Demon Hunter Fel-Scarred 11.2 Class Set 4pc", additional_info = "[q]Verwüstung\n Wenn Ihr Dämonenform annehmt, wird sofort eine Dämonenwoge ausgelöst und ein Dämonenseelenfragment zerbrochen, was 10 Sek. lang 20% Schaden verursacht.\n\nRachsucht\n Wenn Ihr Dämonenform annehmt, wird sofort eine Dämonenwoge ausgelöst und ein Dämonenseelenfragment zerbrochen, was 15 Sek. lang 20% Schaden verursacht.\n\n(100ms Abklingzeit)"}
MultiLanguageSpellData['de'][1236364] = {name = "Evoker Flameshaper 11.2 Class Set 2pc", additional_info = "[q]Der Einsatz von 'Umhüllen' schürt Eure 'Innere Flamme', was Euren regelmäßigen Schaden und Heilung um 25% erhöht und Eure Chance, eine 'Essenzexplosion' zu erhalten, 12 Sek. lang um 50% erhöht. Bis zu 2-mal stapelbar. Mehrere Anwendungen können sich überlappen."}
MultiLanguageSpellData['de'][1236365] = {name = "Evoker Flameshaper 11.2 Class Set 4pc", additional_info = "[q]Verheerung\n Wenn Ihr 'Essenzexplosion' verbraucht, während 'Innere Flamme' aktiv ist, wird eine 'Essenzbombe' auf Euer Ziel abgefeuert, die Gegnern in der Nähe (371% der Zaubermacht) Schaden zufügt. Wird nach dem 5. Ziel reduziert.\n\nBewahrung, Verstärkung\n Wenn Ihr 'Essenzexplosion' verbraucht, während 'Innere Flamme' aktiv ist, wird eine 'Essenzbombe' auf Euer Ziel abgefeuert, die Verbündete in der Nähe um (250% der Zaubermacht) heilt. Wird nach dem 5. Ziel reduziert."}
MultiLanguageSpellData['de'][1236366] = {name = "Evoker Scalecommander 11.2 Class Set 2pc", additional_info = "[q]Verheerung, Bewahrung\n Während Ihr fliegt, solange 'Tiefer Atem' aktiv ist, und 10 Sek. im Anschluss, befehligt Ihr ein Geschwader aus 2 Dracthyr, die Eure Ziele mit 'Desintegrieren' und 'Scheiterhaufen' angreifen.\n\nVerstärkung\n Während Ihr fliegt, solange 'Tiefer Atem' aktiv ist, und 20 Sek. im Anschluss, befehligt Ihr ein Geschwader aus 2 Dracthyr, die Eure Ziele mit 'Desintegrieren' und 'Scheiterhaufen' angreifen."}
MultiLanguageSpellData['de'][1236367] = {name = "Evoker Scalecommander 11.2 Class Set 4pc", additional_info = "[q]Verheerung\n Während Euer Geschwader aktiv ist, treffen Eure Einsätze von 'Massendesintegration' bis zu 2 zusätzliches Ziel. Außerdem unterstützt Euch Euer Geschwader für 5 weitere Sek.\n\nVerstärkung\n Während Euer Geschwader aktiv ist, treffen Eure Einsätze von 'Masseneruption' bis zu 2 zusätzliches Ziel. Außerdem unterstützt Euch Euer Geschwader für 10 weitere Sek.\n\nBewahrung\n Während Euer Geschwader aktiv ist, treffen Eure Einsätze von 'Masseneruption' bis zu 2 zusätzliches Ziel. Außerdem unterstützt Euch Euer Geschwader für 5 weitere Sek."}
MultiLanguageSpellData['de'][1236368] = {name = "Evoker Chronowarden 11.2 Class Set 2pc", additional_info = "[q]Die Abklingzeit von 'Zeitdruck' ist um 60 Sek. verringert."}
MultiLanguageSpellData['de'][1236369] = {name = "Evoker Chronowarden 11.2 Class Set 4pc", additional_info = "[q]Der Einsatz von 'Temporalexplosion' lässt 'Chronoflammen' 2 zusätzliches Ziel treffen und 15% Schaden oder Heilung wiederholen, bis zu einem Maximum von [(Zaubermacht * 4.5) * (1 + Vielseitigkeit)]. Erhöht zudem den Schaden und die Heilung von Essenzfähigkeiten um 30%."}
MultiLanguageSpellData['de'][1236370] = {name = "Hunter Dark Ranger 11.2 Class Set 2pc", additional_info = "[q]Tierherrschaft\n Der Schaden von 'Schwarzer Pfeil' ist um 10% erhöht und der Schaden von 'Düsterpulver' ist um 20% erhöht. Die Abklingzeit von 'Ruf der Wildnis' ist um 60 Sek. verringert.\n\nTreffsicherheit, Überleben\n Der Schaden von 'Schwarzer Pfeil' ist um 10% erhöht und der Schaden von 'Düsterpulver' ist um 20% erhöht. Die Abklingzeit von 'Volltreffer' ist um 30 Sek. verringert."}
MultiLanguageSpellData['de'][1236371] = {name = "Hunter Dark Ranger 11.2 Class Set 4pc", additional_info = "[q]Tierherrschaft, Treffsicherheit, Überleben\n Der Schaden der schwarzen Pfeile durch 'Vernichtendes Feuer' ist um 50% erhöht. Wenn 'Todesstoß' verbraucht wird, besteht eine Chance von 50%, dass während Eures nächsten Einsatzes von 'Vernichtendes Feuer' alle Sperrfeuer 1 zusätzliche schwarze Pfeile verschießen."}
MultiLanguageSpellData['de'][1236372] = {name = "Hunter Pack Leader 11.2 Class Set 2pc", additional_info = "[q]Treffsicherheit, Überleben\n Eure Begleiter verursachen 15% mehr Schaden und Wildtiere 15% mehr Schaden. Die Beschwörung eines Wildtieres verleiht Euch je nach Tierart 8 Sek. lang 6% Tempo, Meisterschaft oder kritische Trefferchance.\n\nTierherrschaft\n Eure Begleiter verursachen 5% mehr Schaden und Wildtiere 15% mehr Schaden. Die Beschwörung eines Wildtieres verleiht Euch je nach Tierart 8 Sek. lang 6% Tempo, Meisterschaft oder kritische Trefferchance."}
MultiLanguageSpellData['de'][1236373] = {name = "Hunter Pack Leader 11.2 Class Set 4pc", additional_info = "[q]Die Beschwörung eines Wildtiers unter dem Effekt von 'Mit gutem Beispiel voran' versetzt die umliegende Tierwelt in eine Stampede, die auf Euer Ziel zustürmt und über 7 Sek. bis zu 8 Gegnern [(300% der Angriffskraft) * 9] körperlichen Schaden zufügt."}
MultiLanguageSpellData['de'][1236374] = {name = "Hunter Sentinel 11.2 Class Set 2pc", additional_info = "[q]Tierherrschaft, Überleben\n Erhöht den Schaden von 'Lauffeuerbombe' um 10%. Wenn 'Lunarsturm' abklingt, erhaltet Ihr eine 'Gabe von Elune', wodurch Ihr mit 'Lauffeuerbombe'$L 2-mal um 150 erhöhten anfänglichen Schaden als Arkanschaden verursacht.\n\nTreffsicherheit\n Erhöht den Schaden von 'Schnellfeuer' um 25%. Wenn 'Lunarsturm' abklingt, erhaltet Ihr eine 'Gabe von Elune', wodurch Ihr mit 'Gezielter Schuss'$L 2-mal um 10 erhöhten Schaden als Arkanschaden verursacht."}
MultiLanguageSpellData['de'][1236375] = {name = "Hunter Sentinel 11.2 Class Set 4pc", additional_info = "[q]Treffsicherheit\n Der Schaden von 'Wachsamer Schütze' ist um 18% erhöht. Die 'Gabe von Elune' ist jetzt für die Dauer von 'Lunarsturm' bei 100% der Effektivität aktiv.\n\nTierherrschaft, Überleben\n Der Schaden von 'Wachsamer Schütze' ist um 20% erhöht. Die 'Gabe von Elune' ist jetzt für die Dauer von 'Lunarsturm' bei 100% der Effektivität aktiv."}
