MultiLanguageSpellData['de'][1236377] = {name = "Monk Master of Harmony 11.2 Class Set 2pc", additional_info = "[q]Braumeister\n Wenn Ihr Lebenskraft erhaltet, besteht eine erhöhte Chance, dass Euer nächster Einsatz von 'Tigerklaue' eine 'Harmonische Welle' auslöst, die auf Euer Ziel und andere Gegner in der Nähe aufgeteilte [180 * (400% der Zaubermacht) / 100] Naturschaden verursacht und bis zu 5 verletzte Verbündete um [20 * (500% der Zaubermacht) / 100] heilt.\n\nWindläufer, Nebelwirker\n Wenn Ihr Lebenskraft erhaltet, besteht eine erhöhte Chance, dass Euer nächster Einsatz von 'Tigerklaue' eine 'Harmonische Welle' auslöst, die auf Euer Ziel und andere Gegner in der Nähe aufgeteilte [20 * (400% der Zaubermacht) / 100] Naturschaden verursacht und bis zu 5 verletzte Verbündete um [90 * (500% der Zaubermacht) / 100] heilt."}
MultiLanguageSpellData['de'][1236378] = {name = "Monk Master of Harmony 11.2 Class Set 4pc", additional_info = "[q]Windläufer, Nebelwirker\n Der Einsatz von 'Donnerfokustee' garantiert, dass Euer Einsatz von 'Tigerklaue' 2-mal eine 'Harmonische Welle' auslöst.\n\nBraumeister\n Der Einsatz von garantiert, dass Euer Einsatz von 'Tigerklaue' 2-mal eine 'Harmonische Welle' auslöst."}
MultiLanguageSpellData['de'][1236379] = {name = "Monk Shado-Pan 11.2 Class Set 2pc", additional_info = "[q]Braumeister\n Euer 'Prügelhagel' verursacht 10% mehr Schaden und die Aktivierung von 'Waffen der Ordnung' generiert sofort 10 Stapel von 'Prügelhagel', die mit 70% Effektivität bei Eurem nächsten Angriff ausgelöst werden.\n\nWindläufer, Nebelwirker\n Euer 'Prügelhagel' verursacht 20% mehr Schaden und die Aktivierung von 'Sturm, Erde und Feuer' generiert sofort 10 Stapel von 'Prügelhagel', die mit 70% Effektivität bei Eurem nächsten Angriff ausgelöst werden."}
MultiLanguageSpellData['de'][1236380] = {name = "Monk Shado-Pan 11.2 Class Set 4pc", additional_info = "[q]Windläufer\n Die Ladungserzeugung für 'Schlaghagel' ist um 50% erhöht und, während 'Sturm, Erde und Feuer aktiv ist, wird pro 150 ausgegebener Energie ein 'Prügelhagel' ausgelöst.\n\nBraumeister, Nebelwirker\n Die Ladungserzeugung für 'Schlaghagel' ist um 50% erhöht und, während 'Waffen der Ordnung' aktiv ist, wird pro 150 ausgegebener Energie ein 'Prügelhagel' ausgelöst."}
MultiLanguageSpellData['de'][1236381] = {name = "Monk Conduit of the Celestials 11.2 Class Set 2pc", additional_info = "[q]Windläufer\n Der Einsatz von 'Herz der Jadeschlange' wird zusätzlich 4 Sek. lang mit 100% Effektivität ausgelöst, nachdem Ihr 'Schneidende Winde' eingesetzt habt.\n\nBraumeister, Nebelwirker\n Der Einsatz von 'Herz der Jadeschlange' wird zusätzlich 8 Sek. lang mit 100% Effektivität ausgelöst, nachdem Ihr 'Donnerfokustee' eingesetzt habt.\n\n(1s Abklingzeit)"}
MultiLanguageSpellData['de'][1236382] = {name = "Monk Conduit of the Celestials 11.2 Class Set 4pc", additional_info = "[q]Der Einsatz von 'Herz der Jadeschlange' erhöht Euer Tempo um 10%, während es aktiv ist, und noch 4 Sek. im Anschluss."}
MultiLanguageSpellData['de'][1236383] = {name = "Paladin Herald of the Sun 11.2 Class Set 2pc", additional_info = "[q]Vergeltung\n Heilung und Schaden von 'Morgenlicht' sind um 30% erhöht und Ihr erhaltet 'Solarzorn', nachdem 'Zornige Vergeltung' ausläuft, was den Effekt von 'Avatar der Sonne' zusätzliche [10][10] Sek. anhalten lässt.\n\nSchutz\n Heilung und Schaden von 'Morgenlicht' sind um 30% erhöht und Ihr erhaltet 'Solarzorn', nachdem 'Zornige Vergeltung' ausläuft, was den Effekt von 'Avatar der Sonne' zusätzliche [10][10] Sek. anhalten lässt.\n\nHeilig (Zornige Vergeltung)\n Heilung und Schaden von 'Morgenlicht' sind um 60% erhöht und Ihr erhaltet 'Solarzorn', nachdem 'Zornige Vergeltung' ausläuft, was den Effekt von 'Avatar der Sonne' zusätzliche 10[10][10] Sek. anhalten lässt."}
MultiLanguageSpellData['de'][1236384] = {name = "Paladin Herald of the Sun 11.2 Class Set 4pc", additional_info = "[q]Vergeltung\n Der Einsatz von 'Solarzorn' erhöht die Effektivität Eurer Heilige Kraft verbrauchenden Fähigkeiten um 15% und verleiht Euch [2][2]-mal 'Morgenlicht'.\n\nSchutz\n Der Einsatz von 'Solarzorn' erhöht die Effektivität Eurer Heilige Kraft verbrauchenden Fähigkeiten um 15% und verleiht Euch [2][2]-mal 'Morgenlicht'.\n\nHeilig (Zornige Vergeltung)\n Der Einsatz von 'Solarzorn' erhöht die Effektivität Eurer Heilige Kraft verbrauchenden Fähigkeiten um 30% und verleiht Euch 2[2][2]-mal 'Morgenlicht'."}
MultiLanguageSpellData['de'][1236385] = {name = "Seelenbombardement", additional_info = nil}
MultiLanguageSpellData['de'][1236389] = {name = "Paladin Lightsmith 11.2 Class Set 2pc", additional_info = "[q]Schutz\n Der Schaden von 'Hammer und Amboss' ist um 15% erhöht und kann außerdem durch mit 40% Effektivität ausgelöst werden.\n\nVergeltung\n Die Heilung von 'Hammer und Amboss' ist um 15% erhöht und kann außerdem durch 'Kreuzfahrerstoß' mit 40% Effektivität ausgelöst werden.\n\nHeilig\n Die Heilung von 'Hammer und Amboss' ist um 15% erhöht und kann außerdem durch 'Kreuzfahrerstoß' mit 75% Effektivität ausgelöst werden.\n\n(750ms Abklingzeit)"}
MultiLanguageSpellData['de'][1236390] = {name = "Paladin Lightsmith 11.2 Class Set 4pc", additional_info = "[q]Der Einsatz von 'Hammer und Amboss' generiert außerdem einen Stapel von 'Meisterwerk', wodurch Euer nächster Einsatz von 'Heilige Bewaffnung' pro Stapel zusätzlich eine geringere Version von sich selbst auf einen Verbündeten in der Nähe wirkt."}
MultiLanguageSpellData['de'][1236391] = {name = "Paladin Templar 11.2 Class Set 2pc", additional_info = "[q]Euer 'Himmelshammer' verursacht 20% mehr kritischen Trefferschaden und seine kritischen Treffer haben eine Chance von 50%, einen zusätzlichen Stapel von 'Errettung des Lichts' zu generieren.\n(Procchance: 50%)"}
MultiLanguageSpellData['de'][1236392] = {name = "Paladin Templar 11.2 Class Set 4pc", additional_info = "[q]Vergeltung\n Euer Einsatz von 'Hammer des Lichts' verursacht 35% erhöhten Schaden gegen das Primärziel, trifft 3 zusätzliche Ziele und kann nach 'Aschewelle' 1-mal öfter eingesetzt werden.\n\nHeilig, Schutz\n Euer Einsatz von 'Hammer des Lichts' verursacht 35% erhöhten Schaden gegen das Primärziel, trifft 3 zusätzliche Ziele und kann nach 'Auge von Tyr' 1-mal öfter eingesetzt werden."}
MultiLanguageSpellData['de'][1236394] = {name = "Priest Oracle 11.2 Class Set 2pc", additional_info = "[q]Heilig, Schatten\nDer Einsatz von 'Gebet der Heilung' heilt Euer Ziel um (1400% der Zaubermacht).\n\nDisziplin\n Der erste Blitz jedes Einsatzes von 'Sühne' verursacht 200% mehr Schaden oder Heilung."}
MultiLanguageSpellData['de'][1236395] = {name = "Priest Oracle 11.2 Class Set 4pc", additional_info = "[q]Der Einsatz von 'Vorahnung der Frömmigkeit' oder 'Vorahnung des Trostes' generiert 2 Stapel von 'Vorahnung der Einsicht mit 100% Effektivität. Wenn ein Stapel von 'Vorahnung der Einsicht' verbraucht wird, erhöht das Euer Tempo 10 Sek. lang um 1.0%. Mehrere Anwendungen können sich überlappen."}
MultiLanguageSpellData['de'][1236396] = {name = "Priest Voidweaver 11.2 Class Set 2pc", additional_info = "[q]Heilig\n Der Einsatz von 'Leerenschlag' ist um 30% erhöht und die Zauberzeit von 'Leerenschlag' ist um 20% reduziert.\n\nSchatten\n Der Einsatz von 'Leerenschlag' ist um 30% erhöht und die Zauberzeit von 'Leerenschlag' ist um 20% reduziert. Die Abklingzeit von 'Leerenschlag' ist um 50% reduziert.\n\nDisziplin\n Der Einsatz von 'Leerenschlag' und 'Sühne' ist um 30% erhöht und die Zauberzeit von 'Leerenschlag' ist um 20% reduziert."}
MultiLanguageSpellData['de'][1236397] = {name = "Priest Voidweaver 11.2 Class Set 4pc", additional_info = "[q]Disziplin\n Der Einsatz von 'Leerenschlag' vergrößert jetzt 'Entropischer Riss', der Einsatz von 'Kollabierende Leere' erhöht den Schaden von 'Entropischer Riss' um weitere 10% und den Schaden Eures nächsten Einsatzes von 'Gedankenschlag' ist basierend auf der Größe des entropischen Risses zum Zeitpunkt des Zusammenbruchs um 200% erhöht.\n\nHeilig, Schatten\n Der Einsatz von 'Leerenschlag' vergrößert jetzt 'Entropischer Riss', der Einsatz von 'Kollabierende Leere' erhöht den Schaden von 'Entropischer Riss' um weitere 10% und den Schaden Eures nächsten Einsatzes von 'Leerenstrom' ist basierend auf der Größe des entropischen Risses zum Zeitpunkt des Zusammenbruchs um 200% erhöht."}
MultiLanguageSpellData['de'][1236398] = {name = "Priest Archon 11.2 Class Set 2pc", additional_info = "[q]Schatten\n Strahlenkränze erzeugen zusätzlich 10 Wahnsinn im Verlauf von 5 Sek. und 'Resonanzenergie' erhöht den Schaden von 'Verschlingende Seuche' um 5.0%.\n\nDisziplin, Heilig\n Strahlenkränze reduzieren die Abklingzeit von 'Segenswort: Epiphanie' und 'Segenswort: Heiligung' um 5 Sek. und 'Resonanzenergie' erhöht die Heilung Eurer Segensworte um 5.0%."}
MultiLanguageSpellData['de'][1236399] = {name = "Priest Archon 11.2 Class Set 4pc", additional_info = "[q]Heilig\n Während 'Kraftwoge' aktiv ist, wird dem Effekt alle 2 Einsätze von 'Segenswort: Epiphanie' oder 'Segenswort: Heiligung' ein weiterer Strahlenkranz mit 100% Effektivität hinzugefügt. Kann bis zu 2-mal auftreten.\n\nDisziplin, Schatten\n Während 'Kraftwoge' aktiv ist, wird dem Effekt alle 2 Einsätze von 'Verschlingende Seuche' ein weiterer Strahlenkranz mit 100% Effektivität hinzugefügt. Kann bis zu 2-mal auftreten."}
MultiLanguageSpellData['de'][1236400] = {name = "Rogue Deathstalker 11.2 Class Set 2pc", additional_info = "[q]Gesetzlosigkeit, Täuschung\n Der Einsatz von 'Symbole des Todes' erhöht während der aktiven Dauer die Effektivität aller Schadenseffekte und Schadensboni von 'Todespirscher' um 40%.\n\nMeucheln\n Der Einsatz von 'Tückische Klinge' erhöht während der aktiven Dauer die Effektivität aller Schadenseffekte und Schadensboni von 'Todespirscher' um 60%."}
MultiLanguageSpellData['de'][1236401] = {name = "Rogue Deathstalker 11.2 Class Set 4pc", additional_info = "[q]Gesetzlosigkeit, Täuschung\n Der Einsatz von 'Symbole des Todes' erhöht während der aktiven Dauer die Effektivität aller Schadenseffekte und Schadensboni von 'Todespirscher' um 40%.\n\nMeucheln\n Der Einsatz von 'Tückische Klinge' erhöht während der aktiven Dauer die Effektivität aller Schadenseffekte und Schadensboni von 'Todespirscher' um 60%."}
MultiLanguageSpellData['de'][1236402] = {name = "Rogue Fatebound 11.2 Class Set 2pc", additional_info = "[q]Gesetzlosigkeit\n Der Einsatz von 'Geisterhafter Schlag' verursacht 50% mehr Schaden und hält 4 Sek. länger an.\n\n Bei 'Grenzfall' eine zusätzliche 'Schicksalsgebundene Münze' geworfen und der Einsatz von 'Geisterhafter Schlag' löst deren Effekt aus.\n\nMeucheln, Täuschung\n Der Einsatz von 'Königsmord' verursacht 10% mehr Schaden und hält 4 Sek. länger an.\n\n Bei 'Grenzfall' eine zusätzliche 'Schicksalsgebundene Münze' geworfen und der Einsatz von 'Königsmord' löst deren Effekt aus."}
MultiLanguageSpellData['de'][1236403] = {name = "Rogue Fatebound 11.2 Class Set 4pc", additional_info = "[q]Gesetzlosigkeit\n Wenn Ihr eine 'Schicksalsgebundene Münze' besitzt, ist die Abklingzeit von 'Adrenalinrausch' um 30.0 Sek. und von 'Geisterhafter Schlag' um 15.0 Sek. reduziert.\n\nMeucheln, Täuschung\n Wenn Ihr eine 'Schicksalsgebundene Münze' besitzt, ist die Abklingzeit von 'Todesmal' um 30.0 Sek. und von 'Königsmord' um 15.0 Sek. reduziert."}
MultiLanguageSpellData['de'][1236404] = {name = "Rogue Trickster 11.2 Class Set 2pc", additional_info = "[q]Der Einsatz von 'Ungesehene Klinge' verursacht 35% mehr Schaden und hat eine Chance von 35%, zweimal zuzuschlagen."}
MultiLanguageSpellData['de'][1236405] = {name = "Rogue Trickster 11.2 Class Set 4pc", additional_info = "[q]Ihr könnt 'Gnadenstoß' jetzt ein zweites Mal innerhalb von 5 Sek. einsetzen und 150% des normalen Schadens verursachen."}
MultiLanguageSpellData['de'][1236406] = {name = "Shaman Farseer 11.2 Class Set 2pc", additional_info = "[q]Der Einsatz von 'Schnelligkeit der Ahnen' beschwört einen ermächtigten Ahnen für 15 Sek., der 10% mehr Schaden und Heilung verursacht."}
MultiLanguageSpellData['de'][1236407] = {name = "Shaman Farseer 11.2 Class Set 4pc", additional_info = "[q]Elementar, Verstärkung\n Der Einsatz von 'Schnelligkeit der Ahnen' erhöht den Schaden und die Heilung Eurer Zauber um 25%, verringert die Manakosten Eurer Zauber um 25% und erhöht die Aufladerate von 'Lavaeruption' 8 Sek. lang um 50%.\n\nWiederherstellung\n Der Einsatz von 'Schnelligkeit der Ahnen' erhöht den Schaden und die Heilung Eurer Zauber um 25%, verringert die Manakosten Eurer Zauber um 25% und erhöht die Aufladerate von 'Lavaeruption' und 'Springflut' 8 Sek. lang um 50%."}
MultiLanguageSpellData['de'][1236408] = {name = "Shaman Stormbringer 11.2 Class Set 2pc", additional_info = "[q]Verstärkung, Wiederherstellung\n Der Einsatz von 'Aszendenz' hat eine Chance von 100%, eine Ladung von 'Sturmgewitter' zu generieren und jeder 8. Einsatz von 'Erwachende Stürme' aktiviert 'Aszendenz' für 6.0 Sek.\n\nElementar\n Der Einsatz von 'Aszendenz' hat eine Chance von 100%, eine Ladung von 'Sturmgewitter' zu generieren und jeder 9. Einsatz von 'Erwachende Stürme' aktiviert 'Aszendenz' für 6.0 Sek.\n\n(100ms Abklingzeit)"}
MultiLanguageSpellData['de'][1236409] = {name = "Shaman Stormbringer 11.2 Class Set 4pc", additional_info = "[q]Elementar, Wiederherstellung\n Euer Naturschaden ist um 3.0% erhöht und während 'Aszendenz' aktiv ist, lassen Eure nächsten Einsätze von 'Sturmgewitter' 2-mal einen Sturm aufziehen, der nach 1.5 Sek. dem Primärziel (960% der Zaubermacht) Naturschaden und Gegnern in der Nähe verringerten Schaden zufügt.\n\nVerstärkung\n Euer Naturschaden ist um 5.0% erhöht und während 'Aszendenz' aktiv ist, lassen Eure nächsten Einsätze von 'Sturmgewitter' 2-mal einen Sturm aufziehen, der nach 1.5 Sek. dem Primärziel (400% der Angriffskraft) Naturschaden und Gegnern in der Nähe verringerten Schaden zufügt.\n\n(100ms Abklingzeit)"}
MultiLanguageSpellData['de'][1236410] = {name = "Shaman Totemic 11.2 Class Set 2pc", additional_info = "[q]Verstärkung\n Nachdem Ihr alle Partikel von 'Wirbelnde Elemente' verbraucht habt, wirkt Euer 'Wogendes Totem' 'Urzeitlicher Sturm' mit 200% Effektivität an [seinem Standort] [dem Standort Eurer Fähigkeit 'Wogendes Totem' ].\n\nElementar, Wiederherstellung\n Nachdem Ihr alle Partikel von 'Wirbelnde Elemente' verbraucht habt, wirkt Ihr 'Platzregen' mit 200% Effektivität an [seinem Standort] [dem Standort Eurer Fähigkeit 'Wogendes Totem' ]."}
MultiLanguageSpellData['de'][1236411] = {name = "Shaman Totemic 11.2 Class Set 4pc", additional_info = "[q]Elementar, Wiederherstellung\n Nachdem Ihr 'Platzregen' eingesetzt habt, wird Eure nächste 'Kettenheilung', 'Heilende Woge' oder 'Welle der Heilung' mit 150% Effektivität erneut ausgelöst.\n\nVerstärkung\n Nachdem Ihr 'Urzeitlicher Sturm' eingesetzt habt, wird Eure nächste 'Lavapeitsche' oder 'Feuernova' mit 150% Effektivität erneut ausgelöst.\n\n(500ms Abklingzeit)"}
MultiLanguageSpellData['de'][1236413] = {name = "Warlock Hellcaller 11.2 Class Set 2pc", additional_info = "[q]Dämonologie, Zerstörung\n Der Einsatz von 'Mal von Xavius' erhöht den Schaden von 'Geschwärzte Seele' um weitere 3% pro Stapel. Der Einsatz von 'Böswilligkeit' erhöht die Anzahl der Stapel von 'Welken' um weitere 2.\n\nGebrechen\n Der Einsatz von 'Mal von Xavius' erhöht den Schaden von 'Geschwärzte Seele' um weitere 6% pro Stapel. Der Einsatz von 'Böswilligkeit' erhöht die Anzahl der Stapel von 'Welken' um weitere 2."}
MultiLanguageSpellData['de'][1236414] = {name = "Warlock Hellcaller 11.2 Class Set 4pc", additional_info = "[q]Gebrechen\n Der Einsatz von 'Böswilligkeit' erzeugt 2 Stapel von 'Gequältes Crescendo' und verhindert, dass 'Geschwärzte Seele' Stapel verbraucht und 8 Sek. lang 25% schneller Schaden verursacht.\n\nDämonologie, Zerstörung\n Der Einsatz von 'Böswilligkeit' erzeugt 2 Stapel von 'Pyrolyse' und verhindert, dass 'Geschwärzte Seele' Stapel verbraucht und 8 Sek. lang 15% schneller Schaden verursacht."}
MultiLanguageSpellData['de'][1236415] = {name = "Warlock Soul Harvester 11.2 Class Set 2pc", additional_info = "[q]Der Einsatz von 'Schatten des Todes' entfesselt Eure 'Dämonenseele' 9 Sek. lang gegen Euer aktuelles Ziel, was dem Ziel (279.306% der Zaubermacht) Schattenschaden und Gegnern innerhalb von 10 Metern (186.209% der Zaubermacht) Schattenschaden zufügt."}
MultiLanguageSpellData['de'][1236416] = {name = "Warlock Soul Harvester 11.2 Class Set 4pc", additional_info = "[q]Der Schaden von 'Dämonenseele' ist um 45% und der Schaden von 'Tückischer Schnitter' um 45% erhöht. Eure 'Dämonenseele' generiert alle 3 Sek. 1 Seelensplitter, während Gegner angegriffen werden."}
MultiLanguageSpellData['de'][1236417] = {name = "Warlock Diabolist 11.2 Class Set 2pc", additional_info = "[q]Dämonologie\n 'Hand von Gul'dan' wird mit voller Macht gewirkt beschwört bis zu 3 dämonische Augen. Wenn 'Dämonische Kunst' verbraucht wird, werden Eure dämonischen Augen auf Euer aktuelles Ziel geschleudert, fügen ihm mit einer Explosion (502.813% der Zaubermacht) Feuerschaden und Gegnern innerhalb von 10 Metern zusätzlich (335.172% der Zaubermacht) Feuerschaden zu.\n\nGebrechen, Zerstörung\n Der Einsatz von 'Chaosblitz', 'Feuerregen' oder 'Schattenbrand' beschwört bis zu 3 dämonische Augen. Wenn 'Dämonische Kunst' verbraucht wird, werden Eure dämonischen Augen auf Euer aktuelles Ziel geschleudert, fügen ihm mit einer Explosion (502.813% der Zaubermacht) Feuerschaden und Gegnern innerhalb von 10 Metern zusätzlich (335.172% der Zaubermacht) Feuerschaden zu."}
MultiLanguageSpellData['de'][1236418] = {name = "Warlock Diabolist 11.2 Class Set 4pc", additional_info = "[q]Dämonische Augen analysieren den Kampf, während sie aktiv sind und liefern Euch Informationen, wenn sie explodieren, was Eure Intelligenz 10 Sek. lang um 2% erhöht."}
MultiLanguageSpellData['de'][1236419] = {name = "Warrior Colossus 11.2 Class Set 2pc", additional_info = "[q]Der Schaden von 'Demolieren' ist um 20% erhöht und der kritische Trefferschaden Eurer Fähigkeiten ist gegen Ziele, die von Eurem 'Demolieren' betroffen sind, ist basierend auf der Anzahl Eurer Stapel von 'Kolossale Macht' 10 Sek. lang um bis zu 20% erhöht."}
MultiLanguageSpellData['de'][1236420] = {name = "Warrior Colossus 11.2 Class Set 4pc", additional_info = "[q]Furor, Schutz\n Der Einsatz von 'Demolieren' erhöht die kritische Trefferchance Eurer nächsten 1 Einsätze von $L'Schildschlag' um 100%. Kritische Treffer von 'Schildschlag' erhöhen den Schaden von 'Verwunden' und 'Tiefe Wunden' 8 Sek. lang um 80%.\n\nWaffen\n Der Einsatz von 'Demolieren' erhöht die kritische Trefferchance Eurer nächsten 1 Einsätze von $L'Tödlicher Stoß' um 100%. Kritische Treffer von 'Tödlicher Stoß' erhöhen den Schaden von 'Verwunden' und 'Tiefe Wunden' 8 Sek. lang um 80%."}
MultiLanguageSpellData['de'][1236421] = {name = "Warrior Mountain Thane 11.2 Class Set 2pc", additional_info = "[q]Eure 'Donnerexplosion' hat eine Chance von 35%, 5-mal 'Ionisierender Schlag' gegen betroffene Ziele auszulösen. Jeder Schlag verursacht (150% der Angriffskraft) Naturschaden."}
MultiLanguageSpellData['de'][1236422] = {name = "Warrior Mountain Thane 11.2 Class Set 4pc", additional_info = "[q]Euer 'Ionisierender Schlag' verursacht 100% mehr Schaden. Zusätzlich erhaltet Ihr beim Auslösen von 'Ionisierender Schlag' eine Ladung von 'Donnerexplosion‘, und Eure nächste 'Donnerexplosion' verursacht 100% mehr Schaden."}
MultiLanguageSpellData['de'][1236423] = {name = "Warrior Slayer 11.2 Class Set 2pc", additional_info = "[q]Der Schaden von 'Hinrichten' ist um 10% erhöht und Eure Hinrichtungen von 'Plötzlicher Tod' haben eine Chance von 10% pro Stapel von 'Überwältigt' auf dem Ziel, einen 'Schlächterschlag' mit 100% Effektivität auszulösen."}
MultiLanguageSpellData['de'][1236424] = {name = "Warrior Slayer 11.2 Class Set 4pc", additional_info = "[q]Furor, Schutz\n Der Schaden von 'Wütender Schlag' ist um 10% erhöht und 'Wütender Schlag' hat eine Chance von 2% pro Stapel, das Ziel zu überwältigen und 'Sturm ernten' mit 150% Effektivität auszulösen.\n\nWaffen\n Der Schaden von 'Überwältigen' ist um 10% erhöht und 'Überwältigen' hat eine Chance von 2% pro Stapel, das Ziel zu überwältigen und 'Sturm ernten' mit 150% Effektivität auszulösen.\n\n(500ms Abklingzeit)"}
