MultiLanguageSpellData['de'][1236792] = {name = "Essenzbombe", additional_info = "30 Meter Reichweite\nSofort\n[q]Verheerung\nWenn Ihr 'Essenzexplosion' verbraucht, während 'Innere Flamme' aktiv ist, wird eine 'Essenzbombe' auf Euer Ziel abgefeuert, die Gegnern in der Nähe (371% der Zaubermacht) Schaden zufügt. Wird nach dem 5. Ziel reduziert.\n\nBewahrung, Verstärkung\nWenn Ihr 'Essenzexplosion' verbraucht, während 'Innere Flamme' aktiv ist, wird eine 'Essenzbombe' auf Euer Ziel abgefeuert, die Verbündete in der Nähe um (250% der Zaubermacht) heilt. Wird nach dem 5. Ziel reduziert."}
MultiLanguageSpellData['de'][1236803] = {name = "Essenzbombe", additional_info = "30 Meter Reichweite\nSofort\n[q]Verheerung\nWenn Ihr 'Essenzexplosion' verbraucht, während 'Innere Flamme' aktiv ist, wird eine 'Essenzbombe' auf Euer Ziel abgefeuert, die Gegnern in der Nähe (371% der Zaubermacht) Schaden zufügt. Wird nach dem 5. Ziel reduziert.\n\nBewahrung, Verstärkung\nWenn Ihr 'Essenzexplosion' verbraucht, während 'Innere Flamme' aktiv ist, wird eine 'Essenzbombe' auf Euer Ziel abgefeuert, die Verbündete in der Nähe um (250% der Zaubermacht) heilt. Wird nach dem 5. Ziel reduziert."}
MultiLanguageSpellData['de'][1236807] = {name = "Gunst der Dryade", additional_info = "Sofort\n[q]Wiederherstellung\nWenn Eure Dryade vergeht, verursachen Eure nächsten 2 Einsätze von 'Rasche Heilung' zusätzliche Heilung in Höhe von 5% der verursachten Heilung, während sie aktiv war, und 25% der Heilung greift auf Verbündete in der Nähe über. Wird nach dem 5. Ziel reduziert.\n\nGleichgewicht, Wildheit, Wächter\nWenn Eure Dryade vergeht, verursachen Eure nächsten 2 Einsätze von 'Sternensog' zusätzlichen Schaden in Höhe von 3% des verursachten Schadens, während sie aktiv war, und 10% des Schadens greift auf Gegner in der Nähe über. Wird nach dem 5. Ziel reduziert."}
MultiLanguageSpellData['de'][1236822] = {name = "Blutrausch", additional_info = "Sofort\n[q]Unheilig\nEure Fähigkeit 'Kummer bereiten' verursacht 30% mehr Schaden und der Einsatz von 'Vampirstoß' erhöht den Schaden Eurer nächsten Einsätze von Ghule 8 Sek. lang um 20%. Mehrere Anwendungen können sich überlappen.\n\nBlut, Frost\nEure Fähigkeit 'Kummer bereiten' verursacht 50% mehr Schaden und der Einsatz von 'Vampirstoß' erhöht den Schaden Eurer nächsten Einsätze von Tanzende Runenwaffen 8 Sek. lang um 20%. Mehrere Anwendungen können sich überlappen."}
