MultiLanguageSpellData['de'][1236989] = {name = "Mondlicht sammeln", additional_info = "Sofort\n[q]Wildheit, Wächter, Wiederherstellung\nEin 'Sternensog', der durch 'Hauen' ausgelöst wurde, spaltet sich beim Einschlag mit 20% Effektivität auf bis zu 3 zusätzliche Ziele auf und erzeugt einen Stapel von 'Mondlicht sammeln'. Der Einsatz von 'Mondstrahl' verbraucht 'Mondlicht sammeln', um Euren Schaden 12 Sek. lang um 4% pro Stapel zu erhöhen.\n\nGleichgewicht\nEin 'Sternensog', der durch 'Sternenfeuer' ausgelöst wurde, spaltet sich beim Einschlag mit 40% Effektivität auf bis zu 3 zusätzliche Ziele auf und erzeugt einen Stapel von 'Mondlicht sammeln'. Der Einsatz von 'Zorn der Elune' oder 'Vollmond' verbraucht 'Mondlicht sammeln', um Euren Schaden 12 Sek. lang um 4% pro Stapel zu erhöhen."}
MultiLanguageSpellData['de'][1236990] = {name = "Mondlichtdurchdringung", additional_info = "Sofort\n[q]Wildheit, Wächter, Wiederherstellung\nEin 'Sternensog', der durch 'Hauen' ausgelöst wurde, spaltet sich beim Einschlag mit 20% Effektivität auf bis zu 3 zusätzliche Ziele auf und erzeugt einen Stapel von 'Mondlicht sammeln'. Der Einsatz von 'Mondstrahl' verbraucht 'Mondlicht sammeln', um Euren Schaden 12 Sek. lang um 4% pro Stapel zu erhöhen.\n\nGleichgewicht\nEin 'Sternensog', der durch 'Sternenfeuer' ausgelöst wurde, spaltet sich beim Einschlag mit 40% Effektivität auf bis zu 3 zusätzliche Ziele auf und erzeugt einen Stapel von 'Mondlicht sammeln'. Der Einsatz von 'Zorn der Elune' oder 'Vollmond' verbraucht 'Mondlicht sammeln', um Euren Schaden 12 Sek. lang um 4% pro Stapel zu erhöhen."}
MultiLanguageSpellData['de'][1236991] = {name = "Verschlingende Leere", additional_info = "100 Meter Reichweite\nSofort\n[q]Wenn Ihr Schaden erleidet, besteht eine hohe Chance, dass Ihr die Essenz von Gegnern in der Nähe verschlingt, was 2116 Schattenschaden auf sie aufteilt und Euch um 150% des verursachten Schadens heilt.\n\n Tödlicher Schaden, der 18656 nicht überschreitet, heilt Euch stattdessen um 20% Eurer Gesundheit und rekonstituiert Euch 6 Sek. lang als instabile Leere. Erreicht 50% Gesundheit, um Euch zu stabilisieren und dem Tod zu entgehen. Dieser Effekt kann einmal pro 8 Min. auftreten. Während der Nukleus sich auflädt, kann der Kern keinen Schaden verursachen."}
MultiLanguageSpellData['de'][1236992] = {name = "Death Knight Deathbringer 11.2 Class Set 4pc", additional_info = nil}
MultiLanguageSpellData['de'][1236993] = {name = "Energieschild", additional_info = "Sofort\n[q]Wenn Ihr Schaden erleidet, habt Ihr eine Chance, einen titanischen Energieschild zu erlangen, der 10 Sek. lang bis zu 3662 Schaden aufhebt. Wenn der Schild abläuft, verursacht er 30% der verbleibenden Absorption als Arkanschaden, aufgeteilt auf Gegner innerhalb von 8 Metern."}
MultiLanguageSpellData['de'][1236996] = {name = "Ermächtigte Seele", additional_info = "Sofort\n[q]Blut, Frost, Unheilig\n'Exterminieren' verursacht 20% mehr Schaden und 'Mal des Schnitters' ist bis zu 15-mal zusätzlich stapelbar. Wenn es explodiert, erhöht 'Mal des Schnitters' Eure kritische Trefferchance 8 Sek. lang um 10%."}
MultiLanguageSpellData['de'][1237011] = {name = "Energiewelle", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Wenn Ihr Schaden erleidet, habt Ihr eine Chance, einen titanischen Energieschild zu erlangen, der 10 Sek. lang bis zu 3662 Schaden aufhebt. Wenn der Schild abläuft, verursacht er 30% der verbleibenden Absorption als Arkanschaden, aufgeteilt auf Gegner innerhalb von 8 Metern."}
