MultiLanguageSpellData['de'][1237067] = {name = "Die Jagd", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Velaryn markiert einen Spielercharakter als ihre Beute, stürmt auf ihn zu und verursacht 63242239 Chaosschaden. Dieser Effekt wird pro Spielercharakter verringert, der im Weg von ' Die Jagd ' steht.\n\n Velaryn greift außerdem alle Spielercharaktere in ihrer Bahn an und fügt allen Spielercharakteren innerhalb von 3 Metern um jeden getroffenen Spielercharakter 9486336 Chaosschaden zu."}
MultiLanguageSpellData['de'][1237068] = {name = "Dimensionsatem", additional_info = "Unbegrenzte Reichweite\nWirken in 2 sek.\n[q]Die Leerenschwinge entfesselt für 4 Sek. einen galaktischen Strahl aus ihrem Kiefer und fügt allen Spielercharakteren darin alle 0.3 Sek. 5621532 kosmischen Schaden zu.\n\n Mehrere Portale werden aufgerissen, aus denen dieser Atem in zusätzliche Richtungen ausgestrahlt wird."}
MultiLanguageSpellData['de'][1237069] = {name = "Senken", additional_info = "Sofort\n[q]Ihr erlangt zu Kampfbeginn 'Elektrische Ladung', die Eure Meisterschaft alle 2 Sek. um 10 erhöht, bis maximal (12 * 10 ). Nach 24 Sek. fällt der Zyklus wieder ab und wiederholt sich."}
