MultiLanguageSpellData['de'][1239494] = {name = "Kosmische Offensive", additional_info = "100 Meter Reichweite\nSofort\n[q]Eure Angriffe haben eine hohe Chance, einen kosmischen Ansturm zu entfesseln, der Eurem Ziel ( 517 * 1 ) kosmischen Schaden zufügt.\n\n Der Schaden wird für jedes Prozent fehlende Gesundheit des Gegners um 2% erhöht und 50% des verursachten Schadens wird auf Gegner in der Nähe aufgeteilt."}
