MultiLanguageSpellData['de'][1241059] = {name = "Himmlische Infusion", additional_info = "{Sofort} {45 sek. Abklingzeit}\n1 Aufladung\n[q]Ein starkes Kräutergebräu, das geläutertes Chi aus Eurem Körper zu einem himmlischen Schutz formt, der 30% des erlittenen Schadens absorbiert. Bis zu [(Angriffskraft * 11.34) * (1 + Vielseitigkeit)].\n\n Das Läutern von gestaffeltem Schaden erhöht die Absorption um bis zu 200%."}
MultiLanguageSpellData['de'][1241070] = {name = "Verlagerter Verschlinger", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Dieser Fresser wurde versehentlich transportiert, als die Mittler Tazavesh verschoben haben, und hat eine neue Welt voller mächtiger Energiequellen gefunden, insbesondere Animaleuchtfeuer... und Reiter.\"\nBeute:\nVerschlingerschwärme\nZone:\nTazavesh"}
MultiLanguageSpellData['de'][1241076] = {name = "Sthaarbs' letztes Mahl", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Wenn zwei kosmisch invasive Bedrohungen aufeinandertreffen, ende die kleinere Bedrohung manchmal auf dem Speiseplan der Größeren. Glücklicherweise zerkauen kosmische Beobachter ihr Essen meist nicht.\"\nBeute:\nSthaarbs\nZone:\nK'aresh"}
MultiLanguageSpellData['de'][1241090] = {name = "Seelenfetzerkugel", additional_info = "200 Meter Reichweite\nSofort\n[q]Eine Energiekugel, die 15 Sek. lang die Bewegungsgeschwindigkeit um 30% und das Tempo um 25% verringert."}
MultiLanguageSpellData['de'][1241095] = {name = "Magma", additional_info = "{Wirken in} {1 sek. 20 sek. Abklingzeit}\n[q]Schleudert Lava auf Gegner innerhalb von 50 Metern und fügt Gegnern innerhalb von 5 Metern um den Einschlagsort 50 Vulkanschaden zu.\n\n Jeder Einschlag beschwört eine Lavakugel, die sich 6 Sek. lang auf einen Gegner fixiert und Gegnern innerhalb von 5 Metern 70 Vulkanschaden zufügt, wenn sie mit einem Gegner kollidiert."}
