MultiLanguageSpellData['de'][1241190] = {name = "Reshii-Verstärkung", additional_info = "Sofort\n[q]Xal'atath erfüllt die Reshiiwickel von Spielercharakteren mit Energie und schützt sie so vor ' Endlose Dunkelheit '."}
MultiLanguageSpellData['de'][1241210] = {name = "Zeichen der Ketten", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Ilyssa platziert ein Zeichen der Ketten an der Position ihres aktuellen Ziels, das sich nach (5 / 2) Sek. aktiviert.\n\n Alle Spielercharaktere werden zu seinem Zentrum hingezogen und verlangsamt, was ihre Bewegungsgeschwindigkeit für 6 Sek. um 60% verringert."}
MultiLanguageSpellData['de'][1241240] = {name = "Aufgeladener Kristall", additional_info = "[q]Eure Zauber und Angriffe haben eine Chance, 'Geladener Blitz' auf Euer Ziel niedergehen zu lassen, was ( 1 * 1206 ) Naturschaden verursacht, aufgeteilt auf Ziele innerhalb von 8 Metern."}
MultiLanguageSpellData['de'][1241241] = {name = "Energieschild", additional_info = "[q]Wenn Ihr Schaden erleidet, habt Ihr eine Chance, einen titanischen Energieschild zu erlangen, der 10 Sek. lang bis zu 3662 Schaden aufhebt. Wenn der Schild abläuft, verursacht er 30% der verbleibenden Absorption als Arkanschaden, aufgeteilt auf Gegner innerhalb von 8 Metern."}
MultiLanguageSpellData['de'][1241242] = {name = "Aufgeladene Berührung", additional_info = "[q]Eure Heilzauber haben eine Chance, auf das Ziel mit der geringsten Gesundheit innerhalb von 40 Metern überzuspringen und es um 1766 Gesundheit zu heilen."}
MultiLanguageSpellData['de'][1241243] = {name = "Elektrische Ladung", additional_info = "[q]Ihr erlangt zu Kampfbeginn 'Elektrische Ladung', die Eure Meisterschaft alle 2 Sek. um 10 erhöht, bis maximal (12 * 10 ). Nach 24 Sek. fällt der Zyklus wieder ab und wiederholt sich."}
MultiLanguageSpellData['de'][1241244] = {name = "Geladene Blitze", additional_info = "[q]Eure Zauber und Fähigkeiten haben eine Chance, Euch in einen Blitzableiter zu verwandeln. Damit trefft Ihr 15 Sek. lang alle 3 Sek. ein zufälliges gegnerisches Ziel innerhalb von 40 Metern und fügt ihm ( 1 * 209 ) Naturschaden zu."}
MultiLanguageSpellData['de'][1241245] = {name = "Kauterisierende Blitze", additional_info = "[q]Eure Zauber und Fähigkeiten haben eine Chance, Euch in einen Blitzableiter zu verwandeln. Damit heilt Ihr 15 Sek. lang alle 3 Sek. den Verbündeten mit der geringsten Gesundheit innerhalb von 40 Metern um 450 Gesundheit."}
MultiLanguageSpellData['de'][1241246] = {name = "Kritische Kette", additional_info = "[q]Eure Zauber und Fähigkeiten haben eine Chance, 'Kritische Überladung' auszulösen, die Euren kritischen Trefferwert 20 Sek. lang alle 2 Sek. um 39 erhöht."}
MultiLanguageSpellData['de'][1241250] = {name = "Statische Aufladung", additional_info = "[q]Eure Zauber und Fähigkeiten haben eine Chance, Euch 'Statische Aufladung' zu gewähren, die Eure Vielseitigkeit 30 Sek. lang um ( 17 * 20) erhöht. Jeder Eurer nächsten Einsätze von Zaubern und Fähigkeiten verringert den Vielseitigkeitsbonus um 5%."}
