MultiLanguageSpellData['de'][1244259] = {name = "Glutversengter Elekk", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Die Brennende Legion war darauf aus, alles zu zerstören, zu stehlen oder zu verderben, was den Draenei Freude bereitete. Und die Elekks von Draenor bildeten da keine Ausnahme.\"\nHandelsposten"}
MultiLanguageSpellData['de'][1244260] = {name = "Leerengeschliffener Elekk", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Ihr Temperament ist so wild wie die verdrehten Kräfte, die ihre Schöpfung verzerrten. Sie dienen nur, wen sie dazu auserkoren haben.\"\nHandelsposten"}
MultiLanguageSpellData['de'][1244261] = {name = "Legionsgeschmiedeter Elekk", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Die Brennende Legion beneidete die Draenei um ihre Bande zu den Elekks von Draenor. Viele dämonische Bestienmeister verderbten die Spezies für ihre eigenen Bedürfnisse, doch kontrollieren konnte sie keiner.\"\nHandelsposten"}
