MultiLanguageSpellData['de'][1244402] = {name = "Augenglas des Essenzjägers", additional_info = "Ca. 10 Procs pro Minute\n[q]Eure kritischen Treffer mit Zaubern und Distanzfähigkeiten haben eine hohe Chance, Euch bis zu 5-mal 'Arkanjäger' zu gewähren, was Euren kritischen Trefferwert für 8 Sek. um 14 pro Stapel erhöht."}
MultiLanguageSpellData['de'][1244405] = {name = "Manageschmiedete Ätherzelle", additional_info = "Ca. 2 Procs pro Minute\n[q]Eure Heilfähigkeiten haben eine Chance, die Ätherzelle mit Energie zu versorgen. Erhöht Eure Meisterschaft um 239 , pro Sekunde um ( 239 / 15) verringert. Hält 15 Sek. lang an."}
MultiLanguageSpellData['de'][1244406] = {name = "Symbiotische Äthergaze", additional_info = "Ca. 2 Procs pro Minute\n[q]Blocken, Parieren und Ausweichen haben eine Chance, die Gaze zu erwecken, sodass sie auf Gegner in der Nähe verteilt 1430 Arkanschaden zufügt und Euch einen Schild gewährt, der 8283 Schaden absorbiert und 15 Sek. lang anhält."}
MultiLanguageSpellData['de'][1244410] = {name = "Körperloser Essenzverschlinger", additional_info = "50 Meter Reichweite\nSofort 2 min Abklingzeit\n[q]Reißt magische Essenz aus Eurem Ziel und verschlingt sie, was dem Ziel ( 612 * 1 ) Arkanschaden zufügt und Euch für 20 Sek. 247 Eures niedrigsten Sekundärwerts gewährt.\n\n Falls das Ziel ein Astraler war, wird stattdessen Euer höchster Sekundärwert erhöht."}
MultiLanguageSpellData['de'][1244414] = {name = "Unberechenbares Ritual", additional_info = "Wirken in 3 sek.\n[q]Der Zaubernde ruft K'aresh an, sodass ätherische Geister in erratischen Mustern nach außen wirbeln. Verursacht Arkanschaden und betäubt Gegner in ihrer Bahn."}
