MultiLanguageSpellData['de'][1245197] = {name = "Schauriges Streitross des kopflosen Reiters", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Fliegt durch die Lüfte, fahrt auf Eure Gegner herab, mit diesem Ross seid Ihr immer auf Zack.\"\nHandelsposten"}
MultiLanguageSpellData['de'][1245198] = {name = "Makabres Streitross des kopflosen Reiters", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Mit süßem Sieg über einen garstigen Reiter, ein ghulisches Ross für einen schaurigen Streiter.\"\nHandelsposten"}
