MultiLanguageSpellData['de'][1245357] = {name = "Geschmückter Greif von Nordaeron", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Die Greifenreiterältesten und Hochschamanen der Wildhämmer von Nordaeron haben ihre Greifen oft mit kunstvollen, federbedeckten Teilen geziert, die ihren Rang und Status zur Schau stellten.\"\nHandelsposten"}
MultiLanguageSpellData['de'][1245358] = {name = "Fluggreif des Hochschamanen", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Die antiken Schamanen der Wildhämmer, die den Greifen als erstes begegneten, glaubten, dass es sich bei ihnen um elementare Geister in sterblicher Form handelte. Diese Begegnung prägte den Wildhammerclan für alle kommenden Generationen.\"\nHandelsposten"}
MultiLanguageSpellData['de'][1245359] = {name = "Glutgefiederter Hochlandgreif", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Laut einer Legende der Wildhämmer soll das orangefarbene Gefieder der Greifen ein vererbtes Merkmal ihrer elementaren Vorfahren sein.\"\nHandelsposten"}
