MultiLanguageSpellData['de'][1245361] = {name = "Himmelsführer der Glutschwinge", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Von den Gebirgsausläufern Khaz Modans sind wir seinen flammenden Schwingen gefolgt... eine Fackel die am dunklen Sommerhimmel gen Norden flog.\" - Die Pilgerfahrt des Ersten Wildweisen\nHandelsposten"}
MultiLanguageSpellData['de'][1245370] = {name = "Störrischer Brisenschreiter", additional_info = "Wirken in 1.5 sek.\n[q]Störrischen Brisenschreiter beschwören oder wieder freigeben.\n[q]\"Dieses Talbuk ist ein stures, eigensinniges Reittier, selbst wenn es mit seinem Reiter vertraut ist. Mit Vorsicht zu genießen.\"\nHandelsposten"}
MultiLanguageSpellData['de'][1245376] = {name = "Arkanjäger", additional_info = "Sofort\n[q]Eure kritischen Treffer mit Zaubern und Distanzfähigkeiten haben eine hohe Chance, Euch bis zu 5-mal 'Arkanjäger' zu gewähren, was Euren kritischen Trefferwert für 8 Sek. um 14 pro Stapel erhöht."}
MultiLanguageSpellData['de'][1245377] = {name = "Verlagerer platzieren", additional_info = "Sofort\n[q]So'azmi setzt paarweise Verlagerer ein, um seine Gegner zu verwirren.\n Bei Berührung eines Verlagerers werden Spielercharaktere sofort zum zugehörigen Verlagerer teleportiert."}
MultiLanguageSpellData['de'][1245384] = {name = "Teufelsinferno", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Velaryn hüllt die Arena in Flammen und fügt allen Spielercharakteren mit jeder erschaffenen Flammensäule 843230 Feuerschaden sowie zusätzlich 15 Sek. lang alle 0.5 Sek. 182700 Feuerschaden zu. Dieser Effekt ist stapelbar.\n\n Die Flamme fügt allen Spielercharakteren, die in den Feuersturm treten, alle 1 Sek. 8435981 Feuerschaden zu."}
MultiLanguageSpellData['de'][1245397] = {name = "Manageschmiedete Ätherzelle", additional_info = "Sofort\n[q]Eure Heilfähigkeiten haben eine Chance, die Ätherzelle mit Energie zu versorgen. Erhöht Eure Meisterschaft um 239 , pro Sekunde um ( 239 / 15) verringert. Hält 15 Sek. lang an."}
MultiLanguageSpellData['de'][1245422] = {name = "Arkaner Tsunami", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Die Seelenbinderin schlägt wütend auf ihr Primärziel ein und fügt diesem bis Abbruch lang alle 5.2 Sek. 0 Arkanschaden zu. Getroffene Spielercharaktere erleiden 45 Sek. lang um 40% erhöhten durch ' Mystische Peitsche ' Schaden und um 15% erhöhten körperlichen Schaden."}
