MultiLanguageSpellData['de'][1245430] = {name = "Arkane Infusion", additional_info = "Sofort\n[q]Der Zaubernde erfüllt alle Spielercharaktere innerhalb von 60 Metern mit arkaner Energie und fügt ihnen 4918841 Arkanschaden und zusätzlich 10 Sek. lang alle 1 Sek. 1194576 Arkanschaden zu.\n\n Zusätzlich erhalten alle jungen Seidenraupen innerhalb von 60 Metern ' Arkane Bisse '."}
MultiLanguageSpellData['de'][1245431] = {name = "Symbiotische Äthergaze", additional_info = "Sofort\n[q]Blocken, Parieren und Ausweichen haben eine Chance, die Gaze zu erwecken, sodass sie auf Gegner in der Nähe verteilt 1430 Arkanschaden zufügt und Euch einen Schild gewährt, der 8283 Schaden absorbiert und 15 Sek. lang anhält."}
MultiLanguageSpellData['de'][1245440] = {name = "K'areshileerenstein", additional_info = "Wirken in 2.5 sek.\n[q]Erfüllt Eure Rüstung mit einem schwachen Echo der Leere, was zusätzliche optische Effekte für bestimmte Klassensetvorlagen der Manaschmiede Omega, freischaltet.\n\n Dieser Effekt gilt für die gesamte Kriegsmeute."}
