MultiLanguageSpellData['de'][1248435] = {name = "Arkane Berührung", additional_info = "Sofort\n[q]Die Zerstörung einer Kiste mit eingestimmter Seide bedeckt die Hände des Spielercharakters 1 Min. lang mit arkaner Energie, die alle 1 Sek. 1 Arkanschaden verursacht.\n\n Während dieser Effekt anhält, besteht die Chance, dass vom Spielercharakter verursachter Schaden dem Ziel 10 Sek. lang alle 1 Sek. 1 regelmäßigen Arkanschaden zufügt. Dieser Effekt ist auf bis zu 10 Anwendungen stapelbar.\n(Procchance: 25%, 3s Abklingzeit)"}
MultiLanguageSpellData['de'][1248447] = {name = "Arkane Berührung", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Die Zerstörung einer Kiste mit eingestimmter Seide bedeckt die Hände des Spielercharakters 1 Min. lang mit arkaner Energie, die alle 1 Sek. 1 Arkanschaden verursacht.\n\n Während dieser Effekt anhält, besteht die Chance, dass vom Spielercharakter verursachter Schaden dem Ziel 10 Sek. lang alle 1 Sek. 1 regelmäßigen Arkanschaden zufügt. Dieser Effekt ist auf bis zu 10 Anwendungen stapelbar."}
