MultiLanguageSpellData['de'][1249454] = {name = "Sternensplitternova", additional_info = "Sofort\n[q]Pargoth entlädt eine Welle überhitzten Sternenstaubs, fügt Spielercharakteren innerhalb von 10 Metern 33729194 kosmischen Schaden zu, verschleudert mehrere Sternensplitter und hinterlässt ' Trümmerfeld '."}
