MultiLanguageSpellData['de'][1249456] = {name = "Sternensplitter", additional_info = "1000 Meter Reichweite\nSofort\n[q]Detoniert heftig nach 12 Sek. oder bei Kontakt mit einem Spielercharakter und fügt allen Spielercharakteren 4 Sek. lang alle 1 Sek. 25 kosmischen Schaden zu. Dieser Effekt ist stapelbar."}
MultiLanguageSpellData['de'][1249462] = {name = "Abmachung: Kartell Zo", additional_info = "Sofort\n[q]Trefft eine Abmachung mit dem Kartell Zo und erlangt das Recht, Euch für eine Woche als eines ihrer Mitglieder zu bezeichnen.\n\n Kriegsmeutenvertrag\n Ihr könnt nur mit einem Kartell pro Woche einen Handel eingehen. Dieser Effekt gilt für Eure gesamte Kriegsmeute."}
MultiLanguageSpellData['de'][1249463] = {name = "[q3]Abmachung: Kartell Zo", additional_info = "Wirken in 3.5 sek.\nReagenzien:\nFrisches Pergament , Manageschmiedetes Instrument , Sonnige Tinte (25)\nVandalen der Manaschmiede\nRuhmstufe:\n8\nOrt:\nSchattenpunkt\n\n[q3]Abmachung: Kartell Zo\n[q2]Benutzen: Trefft eine Abmachung mit dem Kartell Zo und erlangt das Recht, Euch für eine Woche als eines ihrer Mitglieder zu bezeichnen.\n\n Kriegsmeutenvertrag\n Ihr könnt nur mit einem Kartell pro Woche einen Handel eingehen. Dieser Effekt gilt für Eure gesamte Kriegsmeute.\n70\n[q]\"Ein von Schreibern aufgesetzter kurzfristiger \"Vertrag\", der die Loyalität einer Kriegsmeute zu einem Mittlerkartell bekundet.\""}
MultiLanguageSpellData['de'][1249464] = {name = "Gabe von Elune", additional_info = "Sofort\n[q]Tierherrschaft, Überleben\nErhöht den Schaden von 'Lauffeuerbombe' um 10%. Wenn 'Lunarsturm' abklingt, erhaltet Ihr eine 'Gabe von Elune', wodurch Ihr mit 'Lauffeuerbombe'$L 2-mal um 150 erhöhten anfänglichen Schaden als Arkanschaden verursacht.\n\nTreffsicherheit\nErhöht den Schaden von 'Schnellfeuer' um 25%. Wenn 'Lunarsturm' abklingt, erhaltet Ihr eine 'Gabe von Elune', wodurch Ihr mit 'Gezielter Schuss'$L 2-mal um 10 erhöhten Schaden als Arkanschaden verursacht."}
MultiLanguageSpellData['de'][1249465] = {name = "Abmachung: Kartell Ba", additional_info = "Sofort\n[q]Trefft eine Abmachung mit dem Kartell Ba und erlangt das Recht, Euch für eine Woche als eines ihrer Mitglieder zu bezeichnen.\n\n Kriegsmeutenvertrag\n Ihr könnt nur mit einem Kartell pro Woche einen Handel eingehen. Dieser Effekt gilt für Eure gesamte Kriegsmeute."}
